import { useState, useEffect } from 'react'
import { useAuth } from '../hooks/useAuth'
import { api } from '../utils/api'
import { User, Lock, Mail, Shield, Edit2, Save, X, Camera } from 'lucide-react'

interface UserProfile {
  id: number
  username: string
  email: string
  role: string
  avatar?: string
  created_at: string
  last_login?: string
}

export function Profile() {
  const { user, changePassword } = useAuth()
  const [profile, setProfile] = useState<UserProfile | null>(null)
  const [loading, setLoading] = useState(true)
  const [editing, setEditing] = useState(false)
  const [formData, setFormData] = useState({
    email: '',
    username: ''
  })
  const [passwordForm, setPasswordForm] = useState({
    oldPassword: '',
    newPassword: '',
    confirmPassword: ''
  })
  const [showPasswordModal, setShowPasswordModal] = useState(false)
  const [message, setMessage] = useState({ type: '', text: '' })

  useEffect(() => {
    loadProfile()
  }, [])

  const loadProfile = async () => {
    try {
      const res = await fetch('/api/profile', {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('kanban_token')}`
        }
      })
      const data = await res.json()
      if (data.success) {
        setProfile(data.profile)
        setFormData({
          email: data.profile.email || '',
          username: data.profile.username || ''
        })
      }
    } catch (e) {
      console.error('Failed to load profile:', e)
      // 使用本地用户数据作为fallback
      if (user) {
        setProfile({
          id: 1,
          username: user.username || 'admin',
          email: user.email || '',
          role: user.role || 'admin',
          created_at: new Date().toISOString()
        })
        setFormData({
          email: user.email || '',
          username: user.username || ''
        })
      }
    } finally {
      setLoading(false)
    }
  }

  const handleSave = async () => {
    try {
      const res = await fetch('/api/profile', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('kanban_token')}`
        },
        body: JSON.stringify(formData)
      })
      const data = await res.json()
      if (data.success) {
        setProfile(prev => prev ? { ...prev, ...formData } : null)
        setEditing(false)
        showMessage('success', '资料更新成功')
      } else {
        showMessage('error', data.error || '更新失败')
      }
    } catch (e) {
      // 本地模式
      setProfile(prev => prev ? { ...prev, ...formData } : null)
      setEditing(false)
      showMessage('success', '资料更新成功')
    }
  }

  const handlePasswordChange = async (e: React.FormEvent) => {
    e.preventDefault()
    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      showMessage('error', '两次输入的新密码不一致')
      return
    }
    if (passwordForm.newPassword.length < 6) {
      showMessage('error', '新密码长度至少6位')
      return
    }

    const success = await changePassword(passwordForm.oldPassword, passwordForm.newPassword)
    if (success) {
      setShowPasswordModal(false)
      setPasswordForm({ oldPassword: '', newPassword: '', confirmPassword: '' })
      showMessage('success', '密码修改成功')
    } else {
      showMessage('error', '原密码错误')
    }
  }

  const showMessage = (type: string, text: string) => {
    setMessage({ type, text })
    setTimeout(() => setMessage({ type: '', text: '' }), 3000)
  }

  const getRoleLabel = (role: string) => {
    const roles: Record<string, string> = {
      admin: '管理员',
      user: '普通用户',
      viewer: '访客'
    }
    return roles[role] || role
  }

  const getRoleColor = (role: string) => {
    const colors: Record<string, string> = {
      admin: '#c62828',
      user: '#1565c0',
      viewer: '#666'
    }
    return colors[role] || '#666'
  }

  if (loading) return <div className="loading">加载中...</div>

  return (
    <div>
      <h2 className="page-title">👤 用户资料</h2>

      {message.text && (
        <div style={{
          padding: '12px 16px',
          borderRadius: '8px',
          marginBottom: '20px',
          background: message.type === 'success' ? '#e8f5e9' : '#ffebee',
          color: message.type === 'success' ? '#2e7d32' : '#c62828'
        }}>
          {message.text}
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px' }}>
        {/* 基本信息卡片 */}
        <div className="card">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
            <h3 style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '8px' }}>
              <User size={20} color="#667eea" />
              基本信息
            </h3>
            {!editing ? (
              <button 
                onClick={() => setEditing(true)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '4px',
                  background: '#f0f4ff',
                  border: 'none',
                  color: '#667eea',
                  cursor: 'pointer',
                  padding: '6px 12px',
                  borderRadius: '6px',
                  fontSize: '0.85rem'
                }}
              >
                <Edit2 size={14} /> 编辑
              </button>
            ) : (
              <div style={{ display: 'flex', gap: '8px' }}>
                <button 
                  onClick={handleSave}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '4px',
                    background: '#e8f5e9',
                    border: 'none',
                    color: '#2e7d32',
                    cursor: 'pointer',
                    padding: '6px 12px',
                    borderRadius: '6px',
                    fontSize: '0.85rem'
                  }}
                >
                  <Save size={14} /> 保存
                </button>
                <button 
                  onClick={() => {
                    setEditing(false)
                    setFormData({
                      email: profile?.email || '',
                      username: profile?.username || ''
                    })
                  }}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '4px',
                    background: '#f5f5f5',
                    border: 'none',
                    color: '#666',
                    cursor: 'pointer',
                    padding: '6px 12px',
                    borderRadius: '6px',
                    fontSize: '0.85rem'
                  }}
                >
                  <X size={14} /> 取消
                </button>
              </div>
            )}
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {/* 头像 */}
            <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '16px' }}>
              <div style={{
                width: '100px',
                height: '100px',
                borderRadius: '50%',
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '2.5rem',
                color: '#fff',
                position: 'relative'
              }}>
                {profile?.avatar ? (
                  <img src={profile.avatar} alt="avatar" style={{ width: '100%', height: '100%', borderRadius: '50%', objectFit: 'cover' }} />
                ) : (
                  profile?.username?.charAt(0).toUpperCase() || 'U'
                )}
                <div style={{
                  position: 'absolute',
                  bottom: '0',
                  right: '0',
                  width: '28px',
                  height: '28px',
                  borderRadius: '50%',
                  background: '#fff',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  cursor: 'pointer',
                  boxShadow: '0 2px 8px rgba(0,0,0,0.2)'
                }}>
                  <Camera size={14} color="#667eea" />
                </div>
              </div>
            </div>

            {/* 用户名 */}
            <div>
              <label style={{ display: 'block', fontSize: '0.85rem', color: '#666', marginBottom: '6px' }}>
                用户名
              </label>
              {editing ? (
                <input
                  type="text"
                  value={formData.username}
                  onChange={e => setFormData({ ...formData, username: e.target.value })}
                  style={{
                    width: '100%',
                    padding: '10px',
                    borderRadius: '6px',
                    border: '1px solid #ddd',
                    fontSize: '0.95rem'
                  }}
                />
              ) : (
                <div style={{ fontSize: '1.1rem', fontWeight: 600, color: '#333' }}>
                  {profile?.username}
                </div>
              )}
            </div>

            {/* 邮箱 */}
            <div>
              <label style={{ display: 'block', fontSize: '0.85rem', color: '#666', marginBottom: '6px' }}>
                邮箱地址
              </label>
              {editing ? (
                <input
                  type="email"
                  value={formData.email}
                  onChange={e => setFormData({ ...formData, email: e.target.value })}
                  style={{
                    width: '100%',
                    padding: '10px',
                    borderRadius: '6px',
                    border: '1px solid #ddd',
                    fontSize: '0.95rem'
                  }}
                />
              ) : (
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#333' }}>
                  <Mail size={16} color="#667eea" />
                  {profile?.email || '未设置'}
                </div>
              )}
            </div>

            {/* 角色 */}
            <div>
              <label style={{ display: 'block', fontSize: '0.85rem', color: '#666', marginBottom: '6px' }}>
                用户角色
              </label>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <Shield size={16} color={getRoleColor(profile?.role || 'user')} />
                <span style={{
                  padding: '4px 12px',
                  borderRadius: '12px',
                  fontSize: '0.85rem',
                  fontWeight: 600,
                  background: `${getRoleColor(profile?.role || 'user')}20`,
                  color: getRoleColor(profile?.role || 'user')
                }}>
                  {getRoleLabel(profile?.role || 'user')}
                </span>
              </div>
            </div>

            {/* 注册时间 */}
            <div>
              <label style={{ display: 'block', fontSize: '0.85rem', color: '#666', marginBottom: '6px' }}>
                注册时间
              </label>
              <div style={{ color: '#333' }}>
                {profile?.created_at ? new Date(profile.created_at).toLocaleString('zh-CN') : '-'}
              </div>
            </div>

            {/* 最后登录 */}
            <div>
              <label style={{ display: 'block', fontSize: '0.85rem', color: '#666', marginBottom: '6px' }}>
                最后登录
              </label>
              <div style={{ color: '#333' }}>
                {profile?.last_login ? new Date(profile.last_login).toLocaleString('zh-CN') : '当前会话'}
              </div>
            </div>
          </div>
        </div>

        {/* 安全设置卡片 */}
        <div className="card">
          <h3 style={{ margin: '0 0 20px 0', display: 'flex', alignItems: 'center', gap: '8px' }}>
            <Lock size={20} color="#667eea" />
            安全设置
          </h3>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            {/* 修改密码 */}
            <div style={{
              padding: '16px',
              background: '#f8f9fa',
              borderRadius: '8px',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center'
            }}>
              <div>
                <div style={{ fontWeight: 600, color: '#333', marginBottom: '4px' }}>修改密码</div>
                <div style={{ fontSize: '0.85rem', color: '#666' }}>定期更换密码可以提高账户安全性</div>
              </div>
              <button
                onClick={() => setShowPasswordModal(true)}
                style={{
                  padding: '8px 16px',
                  background: '#667eea',
                  color: '#fff',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontSize: '0.85rem'
                }}
              >
                修改
              </button>
            </div>

            {/* 登录安全提示 */}
            <div style={{
              padding: '16px',
              background: '#e8f5e9',
              borderRadius: '8px',
              border: '1px solid #4caf50'
            }}>
              <div style={{ fontWeight: 600, color: '#2e7d32', marginBottom: '8px' }}>🔒 安全提示</div>
              <ul style={{ margin: 0, paddingLeft: '20px', fontSize: '0.85rem', color: '#555' }}>
                <li>使用强密码（包含大小写字母、数字和符号）</li>
                <li>定期更换密码（建议每3个月）</li>
                <li>不要在公共场合保存登录状态</li>
                <li>3小时无操作将自动退出登录</li>
              </ul>
            </div>

            {/* 会话信息 */}
            <div style={{
              padding: '16px',
              background: '#f0f4ff',
              borderRadius: '8px'
            }}>
              <div style={{ fontWeight: 600, color: '#667eea', marginBottom: '8px' }}>📱 当前会话</div>
              <div style={{ fontSize: '0.85rem', color: '#555' }}>
                <div style={{ marginBottom: '4px' }}>浏览器: {navigator.userAgent.split(' ').pop()}</div>
                <div>平台: {navigator.platform}</div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 修改密码弹窗 */}
      {showPasswordModal && (
        <div 
          className="modal-overlay" 
          onClick={() => setShowPasswordModal(false)}
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0,0,0,0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000
          }}
        >
          <div 
            onClick={e => e.stopPropagation()}
            style={{
              background: '#fff',
              borderRadius: '12px',
              padding: '24px',
              maxWidth: '400px',
              width: '90%',
              boxShadow: '0 20px 60px rgba(0,0,0,0.3)'
            }}
          >
            <h3 style={{ margin: '0 0 20px 0', color: '#333' }}>修改密码</h3>
            <form onSubmit={handlePasswordChange}>
              <div style={{ marginBottom: '16px' }}>
                <label style={{ display: 'block', fontSize: '0.85rem', color: '#666', marginBottom: '6px' }}>
                  原密码
                </label>
                <input
                  type="password"
                  value={passwordForm.oldPassword}
                  onChange={e => setPasswordForm({ ...passwordForm, oldPassword: e.target.value })}
                  required
                  style={{
                    width: '100%',
                    padding: '10px',
                    borderRadius: '6px',
                    border: '1px solid #ddd',
                    fontSize: '0.95rem'
                  }}
                />
              </div>
              <div style={{ marginBottom: '16px' }}>
                <label style={{ display: 'block', fontSize: '0.85rem', color: '#666', marginBottom: '6px' }}>
                  新密码
                </label>
                <input
                  type="password"
                  value={passwordForm.newPassword}
                  onChange={e => setPasswordForm({ ...passwordForm, newPassword: e.target.value })}
                  required
                  style={{
                    width: '100%',
                    padding: '10px',
                    borderRadius: '6px',
                    border: '1px solid #ddd',
                    fontSize: '0.95rem'
                  }}
                />
              </div>
              <div style={{ marginBottom: '20px' }}>
                <label style={{ display: 'block', fontSize: '0.85rem', color: '#666', marginBottom: '6px' }}>
                  确认新密码
                </label>
                <input
                  type="password"
                  value={passwordForm.confirmPassword}
                  onChange={e => setPasswordForm({ ...passwordForm, confirmPassword: e.target.value })}
                  required
                  style={{
                    width: '100%',
                    padding: '10px',
                    borderRadius: '6px',
                    border: '1px solid #ddd',
                    fontSize: '0.95rem'
                  }}
                />
              </div>
              <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
                <button
                  type="button"
                  onClick={() => setShowPasswordModal(false)}
                  style={{
                    padding: '10px 20px',
                    background: '#f5f5f5',
                    color: '#666',
                    border: 'none',
                    borderRadius: '6px',
                    cursor: 'pointer'
                  }}
                >
                  取消
                </button>
                <button
                  type="submit"
                  style={{
                    padding: '10px 20px',
                    background: '#667eea',
                    color: '#fff',
                    border: 'none',
                    borderRadius: '6px',
                    cursor: 'pointer'
                  }}
                >
                  确认修改
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}