export function GoalsDetail() {
  const [goals, setGoals] = useState<GoalDetail[]>(defaultGoals)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editContent, setEditContent] = useState('')
  const [selectedGoal, setSelectedGoal] = useState<GoalDetail | null>(null)

  useEffect(() => {
    // 从localStorage加载保存的内容
    const saved = localStorage.getItem('goalsDetail')
    if (saved) {
      try {
        const parsed = JSON.parse(saved)
        setGoals(prev => prev.map(g => parsed[g.id] ? { ...g, content: parsed[g.id] } : g))
      } catch (e) {
        console.error('Failed to load saved goals:', e)
      }
    }
  }, [])

  const startEdit = (goal: GoalDetail) => {
    setEditingId(goal.id)
    setEditContent(goal.content)
    setSelectedGoal(goal)
  }

  const saveEdit = () => {
    if (!editingId) return
    
    const updatedGoals = goals.map(g => 
      g.id === editingId ? { ...g, content: editContent, updatedAt: new Date().toISOString().split('T')[0] } : g
    )
    setGoals(updatedGoals)
    
    // 保存到localStorage
    const savedData: Record<string, string> = {}
    updatedGoals.forEach(g => {
      savedData[g.id] = g.content
    })
    localStorage.setItem('goalsDetail', JSON.stringify(savedData))
    
    setEditingId(null)
    setEditContent('')
    setSelectedGoal(null)
  }

  const cancelEdit = () => {
    setEditingId(null)
    setEditContent('')
    setSelectedGoal(null)
  }

  return (
    <div className="page-container">
      {/* Header */}
      <div className="page-header">
        <div>
          <Link to="/my-goals" style={{ textDecoration: 'none', color: '#667eea', display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px' }}>
            <ArrowLeft size={20} />
            返回我的人生目标
          </Link>
          <h2 className="page-title">📋 目标原本</h2>
          <p style={{ color: '#666', marginTop: '8px' }}>
            七大核心目标的详细规划和执行要求
          </p>
        </div>
      </div>

      {/* Goals List */}
      <div style={{ display: 'grid', gap: '16px' }}>
        {goals.map((goal) => (
          <div key={goal.id} className="card" style={{ marginBottom: '0' }}>
            <div style={{ 
              display: 'flex', 
              justifyContent: 'space-between', 
              alignItems: 'flex-start',
              marginBottom: '16px'
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <span style={{ fontSize: '32px' }}>{goal.icon}</span>
                <div>
                  <h3 style={{ margin: 0, fontSize: '1.2rem' }}>{goal.title}</h3>
                  <p style={{ margin: '4px 0 0 0', color: '#888', fontSize: '0.85rem' }}>
                    最后更新: {goal.updatedAt}
                  </p>
                </div>
              </div>
              {editingId === goal.id ? (
                <div style={{ display: 'flex', gap: '8px' }}>
                  <button className="btn btn-success" onClick={saveEdit}>
                    <Save size={16} /> 保存
                  </button>
                  <button className="btn btn-secondary" onClick={cancelEdit}>
                    取消
                  </button>
                </div>
              ) : (
                <button className="btn btn-primary" onClick={() => startEdit(goal)}>
                  <Edit2 size={16} /> 编辑
                </button>
              )}
            </div>

            {editingId === goal.id ? (
              <textarea
                value={editContent}
                onChange={(e) => setEditContent(e.target.value)}
                style={{
                  width: '100%',
                  minHeight: '400px',
                  padding: '16px',
                  fontSize: '14px',
                  lineHeight: '1.8',
                  fontFamily: 'monospace',
                  border: '2px solid #667eea',
                  borderRadius: '8px',
                  resize: 'vertical'
                }}
              />
            ) : (
              <div 
                style={{
                  background: '#f8f9fa',
                  padding: '20px',
                  borderRadius: '8px',
                  fontSize: '14px',
                  lineHeight: '1.8',
                  whiteSpace: 'pre-wrap',
                  maxHeight: selectedGoal?.id === goal.id ? 'none' : '300px',
                  overflow: selectedGoal?.id === goal.id ? 'visible' : 'auto'
                }}
              >
                {goal.content}
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Summary Stats */}
      <div className="stats-grid" style={{ marginTop: '24px' }}>
        <div className="stat-card">
          <Target size={32} color="#667eea" />
          <div className="stat-value">7</div>
          <div className="stat-label">核心目标</div>
        </div>
        <div className="stat-card">
          <Cpu size={32} color="#28a745" />
          <div className="stat-value">∞</div>
          <div className="stat-label">持续优化</div>
        </div>
        <div className="stat-card">
          <Building2 size={32} color="#ff6b6b" />
          <div className="stat-value">10亿</div>
          <div className="stat-label">估值目标</div>
        </div>
        <div className="stat-card">
          <GraduationCap size={32} color="#ffc107" />
          <div className="stat-value">院士</div>
          <div className="stat-label">学术目标</div>
        </div>
      </div>
    </div>
  )
}
