import { useState, useEffect, useRef, useCallback } from 'react'
import { 
  Edit2, Save, Plus, Trash2, Move, FileText, Settings, 
  RotateCw as Sync, Undo, History, X, Check, Link, Unlink, ZoomIn, ZoomOut
} from 'lucide-react'

interface WorkflowNode {
  id: number
  name: string
  type: 'node' | 'file'
  x: number
  y: number
  color: string
  file_path: string
  description: string
}

interface WorkflowConnection {
  id: number
  from_node: number
  to_node: number
}

interface Version {
  id: number
  version: number
  created_at: string
  description: string
}

export function ArchitectureEditable() {
  const [zoom, setZoom] = useState(1)
  const [isEditMode, setIsEditMode] = useState(false)
  const [selectedNode, setSelectedNode] = useState<WorkflowNode | null>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 })
  const [nodes, setNodes] = useState<WorkflowNode[]>([])
  const [connections, setConnections] = useState<WorkflowConnection[]>([])
  const [versions, setVersions] = useState<Version[]>([])
  const [showVersionHistory, setShowVersionHistory] = useState(false)
  const [editingNode, setEditingNode] = useState<WorkflowNode | null>(null)
  const [isConnecting, setIsConnecting] = useState(false)
  const [connectionStart, setConnectionStart] = useState<number | null>(null)
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 })
  const svgRef = useRef<SVGSVGElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)

  // 加载数据
  useEffect(() => {
    loadData()
  }, [])

  const loadData = async () => {
    try {
      const response = await fetch('/api/workflow-architecture')
      const result = await response.json()
      
      if (result.success) {
        setNodes(result.data.nodes)
        setConnections(result.data.connections)
      }
    } catch (error) {
      console.error('加载数据失败:', error)
    }
  }

  // 保存架构图
  const saveArchitecture = async () => {
    try {
      const response = await fetch('/api/workflow-architecture', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ nodes, connections })
      })
      
      const result = await response.json()
      
      if (result.success) {
        alert('✅ 架构图已保存')
        loadData()
      } else {
        alert('❌ 保存失败：' + result.error)
      }
    } catch (error) {
      console.error('保存失败:', error)
      alert('❌ 保存失败')
    }
  }

  // 同步文件
  const syncFiles = async () => {
    try {
      const response = await fetch('/api/workflow-architecture/sync', {
        method: 'POST'
      })
      
      const result = await response.json()
      
      if (result.success) {
        alert(`✅ 已同步 ${result.synced_files.length} 个文件：${result.synced_files.join(', ')}`)
        loadData()
      } else {
        alert('❌ 同步失败：' + result.error)
      }
    } catch (error) {
      console.error('同步失败:', error)
      alert('❌ 同步失败')
    }
  }

  // 加载版本历史
  const loadVersions = async () => {
    try {
      const response = await fetch('/api/workflow-architecture/versions')
      const result = await response.json()
      
      if (result.success) {
        setVersions(result.versions)
        setShowVersionHistory(true)
      }
    } catch (error) {
      console.error('加载版本历史失败:', error)
    }
  }

  // 恢复版本
  const restoreVersion = async (versionId: number) => {
    if (!confirm('确定要恢复到此版本吗？当前修改将会丢失。')) {
      return
    }

    try {
      const response = await fetch(`/api/workflow-architecture/versions/${versionId}/restore`, {
        method: 'POST'
      })
      
      const result = await response.json()
      
      if (result.success) {
        alert(`✅ 已恢复到版本 ${result.new_version}`)
        setShowVersionHistory(false)
        loadData()
      } else {
        alert('❌ 恢复失败：' + result.error)
      }
    } catch (error) {
      console.error('恢复失败:', error)
      alert('❌ 恢复失败')
    }
  }

  // 处理鼠标移动
  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    if (!containerRef.current) return
    
    const rect = containerRef.current.getBoundingClientRect()
    setMousePos({
      x: (e.clientX - rect.left) / zoom,
      y: (e.clientY - rect.top) / zoom
    })

    if (isDragging && selectedNode) {
      setNodes(prev => prev.map(node => {
        if (node.id === selectedNode.id) {
          return {
            ...node,
            x: e.clientX / zoom - dragOffset.x,
            y: e.clientY / zoom - dragOffset.y
          }
        }
        return node
      }))
    }
  }, [isDragging, selectedNode, dragOffset, zoom])

  // 处理鼠标松开
  const handleMouseUp = useCallback(() => {
    setIsDragging(false)
    
    if (isConnecting && connectionStart !== null) {
      setIsConnecting(false)
      setConnectionStart(null)
    }
  }, [isConnecting, connectionStart])

  // 开始拖拽节点
  const handleNodeMouseDown = (e: React.MouseEvent, node: WorkflowNode) => {
    if (!isEditMode) return
    
    e.stopPropagation()
    setSelectedNode(node)
    setIsDragging(true)
    
    const rect = (e.target as HTMLElement).getBoundingClientRect()
    setDragOffset({
      x: e.clientX / zoom - node.x,
      y: e.clientY / zoom - node.y
    })
  }

  // 开始创建连接
  const handleConnectionStart = (e: React.MouseEvent, nodeId: number) => {
    if (!isEditMode) return
    
    e.stopPropagation()
    setIsConnecting(true)
    setConnectionStart(nodeId)
  }

  // 完成创建连接
  const handleConnectionEnd = (e: React.MouseEvent, nodeId: number) => {
    if (!isConnecting || connectionStart === null || connectionStart === nodeId) return
    
    // 检查连接是否已存在
    const exists = connections.some(
      c => c.from_node === connectionStart && c.to_node === nodeId
    )
    
    if (!exists) {
      setConnections(prev => [...prev, {
        id: Date.now(),
        from_node: connectionStart,
        to_node: nodeId
      }])
    }
    
    setIsConnecting(false)
    setConnectionStart(null)
  }

  // 删除连接
  const deleteConnection = (connId: number) => {
    setConnections(prev => prev.filter(c => c.id !== connId))
  }

  // 编辑节点
  const editNode = (node: WorkflowNode) => {
    setEditingNode({ ...node })
  }

  // 保存节点编辑
  const saveNodeEdit = () => {
    if (!editingNode) return
    
    setNodes(prev => prev.map(node => 
      node.id === editingNode.id ? editingNode : node
    ))
    setEditingNode(null)
  }

  // 删除节点
  const deleteNode = (nodeId: number) => {
    if (!confirm('确定要删除这个节点吗？')) return
    
    setNodes(prev => prev.filter(n => n.id !== nodeId))
    setConnections(prev => prev.filter(c => c.from_node !== nodeId && c.to_node !== nodeId))
    setSelectedNode(null)
  }

  // 添加新节点
  const addNewNode = () => {
    const newNode: WorkflowNode = {
      id: Date.now(),
      name: '新节点',
      type: 'node',
      x: 100,
      y: 100,
      color: '#e3f2fd',
      file_path: '',
      description: ''
    }
    setNodes(prev => [...prev, newNode])
    setEditingNode(newNode)
  }

  // 计算连接线的路径
  const getConnectionPath = (fromNode: WorkflowNode, toNode: WorkflowNode) => {
    const fromX = fromNode.x + 100
    const fromY = fromNode.y + 40
    const toX = toNode.x + 100
    const toY = toNode.y + 40
    
    const midX = (fromX + toX) / 2
    
    return `M ${fromX} ${fromY} C ${midX} ${fromY}, ${midX} ${toY}, ${toX} ${toY}`
  }

  return (
    <div className="h-screen w-screen bg-gray-50 flex flex-col overflow-hidden">
      {/* 工具栏 */}
      <div className="bg-white border-b border-gray-200 p-4 flex items-center justify-between shadow-sm">
        <div className="flex items-center space-x-4">
          <h1 className="text-xl font-bold text-gray-800">🏗️ Dudu 工作流程架构图</h1>
          
          <div className="flex items-center space-x-2 border-l border-gray-300 pl-4">
            <button
              onClick={() => setIsEditMode(!isEditMode)}
              className={`px-3 py-2 rounded-lg flex items-center space-x-2 transition-colors ${
                isEditMode 
                  ? 'bg-blue-500 text-white hover:bg-blue-600' 
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <Edit2 size={16} />
              <span>{isEditMode ? '编辑中' : '编辑模式'}</span>
            </button>
            
            <button
              onClick={saveArchitecture}
              className="px-3 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 flex items-center space-x-2 transition-colors"
            >
              <Save size={16} />
              <span>保存</span>
            </button>
            
            <button
              onClick={syncFiles}
              className="px-3 py-2 bg-purple-500 text-white rounded-lg hover:bg-purple-600 flex items-center space-x-2 transition-colors"
            >
              <Sync size={16} />
              <span>同步文件</span>
            </button>
            
            <button
              onClick={loadVersions}
              className="px-3 py-2 bg-orange-500 text-white rounded-lg hover:bg-orange-600 flex items-center space-x-2 transition-colors"
            >
              <History size={16} />
              <span>历史版本</span>
            </button>
          </div>
        </div>
        
        <div className="flex items-center space-x-2">
          <button
            onClick={() => setZoom(Math.max(0.5, zoom - 0.1))}
            className="p-2 bg-gray-100 rounded-lg hover:bg-gray-200"
          >
            <ZoomOut size={16} />
          </button>
          <span className="text-sm text-gray-600 w-16 text-center">{Math.round(zoom * 100)}%</span>
          <button
            onClick={() => setZoom(Math.min(2, zoom + 0.1))}
            className="p-2 bg-gray-100 rounded-lg hover:bg-gray-200"
          >
            <ZoomIn size={16} />
          </button>
        </div>
      </div>

      {/* 画布区域 */}
      <div 
        ref={containerRef}
        className="flex-1 relative overflow-auto bg-gradient-to-br from-gray-50 to-gray-100"
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >
        <svg
          ref={svgRef}
          className="w-full h-full"
          style={{ 
            transform: `scale(${zoom})`,
            transformOrigin: 'top left',
            minWidth: '2000px',
            minHeight: '1500px'
          }}
        >
          {/* 网格背景 */}
          <defs>
            <pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse">
              <path d="M 20 0 L 0 0 0 20" fill="none" stroke="#e5e7eb" strokeWidth="0.5"/>
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#grid)" />

          {/* 连接线 */}
          <g className="connections">
            {connections.map(conn => {
              const fromNode = nodes.find(n => n.id === conn.from_node)
              const toNode = nodes.find(n => n.id === conn.to_node)
              
              if (!fromNode || !toNode) return null
              
              return (
                <g key={conn.id}>
                  <path
                    d={getConnectionPath(fromNode, toNode)}
                    fill="none"
                    stroke="#9ca3af"
                    strokeWidth="2"
                    markerEnd="url(#arrowhead)"
                  />
                  {isEditMode && (
                    <circle
                      cx={(fromNode.x + toNode.x) / 2 + 100}
                      cy={(fromNode.y + toNode.y) / 2 + 40}
                      r="8"
                      fill="#ef4444"
                      className="cursor-pointer hover:fill-red-600"
                      onClick={() => deleteConnection(conn.id)}
                    />
                  )}
                </g>
              )
            })}
            
            {/* 正在创建的连接线 */}
            {isConnecting && connectionStart !== null && (
              <path
                d={`M ${nodes.find(n => n.id === connectionStart)?.x! + 100} ${nodes.find(n => n.id === connectionStart)?.y! + 40} L ${mousePos.x} ${mousePos.y}`}
                fill="none"
                stroke="#3b82f6"
                strokeWidth="2"
                strokeDasharray="5,5"
              />
            )}
          </g>

          {/* 箭头标记 */}
          <defs>
            <marker
              id="arrowhead"
              markerWidth="10"
              markerHeight="7"
              refX="9"
              refY="3.5"
              orient="auto"
            >
              <polygon points="0 0, 10 3.5, 0 7" fill="#9ca3af" />
            </marker>
          </defs>

          {/* 节点 */}
          <g className="nodes">
            {nodes.map(node => (
              <g
                key={node.id}
                transform={`translate(${node.x}, ${node.y})`}
                className="cursor-pointer"
                onMouseDown={(e) => handleNodeMouseDown(e, node)}
                onClick={(e) => {
                  e.stopPropagation()
                  if (isConnecting && connectionStart !== null) {
                    handleConnectionEnd(e, node.id)
                  } else {
                    setSelectedNode(node)
                  }
                }}
                onDoubleClick={() => isEditMode && editNode(node)}
              >
                {/* 节点背景 */}
                <rect
                  width="200"
                  height="80"
                  rx="8"
                  fill={node.color}
                  stroke={selectedNode?.id === node.id ? '#3b82f6' : '#d1d5db'}
                  strokeWidth={selectedNode?.id === node.id ? 3 : 1}
                  className="transition-all duration-200"
                />
                
                {/* 节点类型图标 */}
                {node.type === 'file' && (
                  <text x="10" y="25" fontSize="16">📄</text>
                )}
                
                {/* 节点名称 */}
                <text
                  x="35"
                  y="25"
                  fontSize="14"
                  fontWeight="bold"
                  fill="#1f2937"
                >
                  {node.name}
                </text>
                
                {/* 节点描述 */}
                <text
                  x="35"
                  y="45"
                  fontSize="11"
                  fill="#6b7280"
                >
                  {node.description?.substring(0, 25) || ''}
                  {node.description && node.description.length > 25 ? '...' : ''}
                </text>
                
                {/* 连接按钮（编辑模式） */}
                {isEditMode && (
                  <circle
                    cx="190"
                    cy="40"
                    r="12"
                    fill="#3b82f6"
                    className="cursor-pointer hover:fill-blue-600"
                    onClick={(e) => handleConnectionStart(e, node.id)}
                  />
                )}
                {isEditMode && (
                  <text
                    x="190"
                    y="44"
                    fontSize="14"
                    fill="white"
                    textAnchor="middle"
                  >
                    +
                  </text>
                )}
              </g>
            ))}
          </g>
        </svg>

        {/* 添加节点按钮 */}
        {isEditMode && (
          <button
            onClick={addNewNode}
            className="absolute bottom-8 right-8 w-16 h-16 bg-blue-500 text-white rounded-full shadow-lg hover:bg-blue-600 flex items-center justify-center transition-colors"
            style={{ transform: `scale(${zoom})`, transformOrigin: 'bottom right' }}
          >
            <Plus size={32} />
          </button>
        )}
      </div>

      {/* 节点编辑弹窗 */}
      {editingNode && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl p-6 w-full max-w-md">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold">编辑节点</h2>
              <button
                onClick={() => setEditingNode(null)}
                className="text-gray-500 hover:text-gray-700"
              >
                <X size={24} />
              </button>
            </div>
            
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  名称
                </label>
                <input
                  type="text"
                  value={editingNode.name}
                  onChange={(e) => setEditingNode({ ...editingNode, name: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                />
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  类型
                </label>
                <select
                  value={editingNode.type}
                  onChange={(e) => setEditingNode({ ...editingNode, type: e.target.value as 'node' | 'file' })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                >
                  <option value="node">流程节点</option>
                  <option value="file">文件节点</option>
                </select>
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  颜色
                </label>
                <input
                  type="color"
                  value={editingNode.color}
                  onChange={(e) => setEditingNode({ ...editingNode, color: e.target.value })}
                  className="w-full h-10 border border-gray-300 rounded-lg cursor-pointer"
                />
              </div>
              
              {editingNode.type === 'file' && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    关联文件
                  </label>
                  <input
                    type="text"
                    value={editingNode.file_path}
                    onChange={(e) => setEditingNode({ ...editingNode, file_path: e.target.value })}
                    placeholder="例如：SOUL.md"
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                  />
                </div>
              )}
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  描述
                </label>
                <textarea
                  value={editingNode.description}
                  onChange={(e) => setEditingNode({ ...editingNode, description: e.target.value })}
                  rows={3}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                />
              </div>
              
              <div className="flex space-x-3 pt-4">
                <button
                  onClick={() => {
                    deleteNode(editingNode.id)
                    setEditingNode(null)
                  }}
                  className="flex-1 px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 flex items-center justify-center space-x-2"
                >
                  <Trash2 size={16} />
                  <span>删除</span>
                </button>
                <button
                  onClick={saveNodeEdit}
                  className="flex-1 px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 flex items-center justify-center space-x-2"
                >
                  <Check size={16} />
                  <span>保存</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 版本历史弹窗 */}
      {showVersionHistory && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl p-6 w-full max-w-2xl max-h-[80vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold">📚 版本历史</h2>
              <button
                onClick={() => setShowVersionHistory(false)}
                className="text-gray-500 hover:text-gray-700"
              >
                <X size={24} />
              </button>
            </div>
            
            <div className="space-y-3">
              {versions.map(ver => (
                <div
                  key={ver.id}
                  className="flex items-center justify-between p-4 border border-gray-200 rounded-lg hover:bg-gray-50"
                >
                  <div>
                    <div className="font-semibold text-gray-800">版本 {ver.version}</div>
                    <div className="text-sm text-gray-500">{ver.description}</div>
                    <div className="text-xs text-gray-400 mt-1">
                      {new Date(ver.created_at).toLocaleString('zh-CN')}
                    </div>
                  </div>
                  <button
                    onClick={() => restoreVersion(ver.id)}
                    className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 flex items-center space-x-2"
                  >
                    <Undo size={16} />
                    <span>恢复</span>
                  </button>
                </div>
              ))}
              
              {versions.length === 0 && (
                <div className="text-center text-gray-500 py-8">
                  暂无版本历史
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* 提示信息 */}
      {!isEditMode && (
        <div className="fixed bottom-4 left-1/2 transform -translate-x-1/2 bg-gray-800 text-white px-6 py-3 rounded-lg shadow-lg text-sm">
          💡 点击"编辑模式"开始编辑架构图，拖拽节点调整位置，双击节点编辑属性
        </div>
      )}
    </div>
  )
}
