import { useState, useEffect } from 'react'
import { User, Mail, Phone, MapPin, Briefcase, GraduationCap, Award, Edit2, Save, X, Plus, Trash2 } from 'lucide-react'

interface Person {
  id: string
  name: string
  title: string
  email: string
  phone: string
  location: string
  bio: string
  avatar?: string
  skills: string[]
  education: Education[]
  experience: Experience[]
  certifications: Certification[]
}

interface Education {
  id: string
  school: string
  degree: string
  field: string
  startYear: string
  endYear: string
}

interface Experience {
  id: string
  company: string
  position: string
  description: string
  startDate: string
  endDate: string
}

interface Certification {
  id: string
  name: string
  issuer: string
  date: string
  expiry?: string
}

const defaultPerson: Person = {
  id: '1',
  name: '刘宇宙',
  title: '蓝天青年学者（二级）',
  email: 'liuyuzhou@buaa.edu.cn',
  phone: '138-0000-0000',
  location: '北京',
  bio: '北京航空航天大学化学学院教授，专注于计算化学和AI材料研发。',
  skills: ['计算化学', 'AI', 'Python', '量子化学', '材料模拟'],
  education: [
    { id: '1', school: '北京大学', degree: '博士', field: '化学', startYear: '2005', endYear: '2010' }
  ],
  experience: [
    { id: '1', company: '北京航空航天大学', position: '教授', description: '从事计算化学研究', startDate: '2015', endDate: '至今' }
  ],
  certifications: [
    { id: '1', name: '蓝天青年学者', issuer: '北航', date: '2020' }
  ]
}

export function PersonalInfo() {
  const [person, setPerson] = useState<Person>(defaultPerson)
  const [isEditing, setIsEditing] = useState(false)
  const [editData, setEditData] = useState<Person>(defaultPerson)
  const [activeTab, setActiveTab] = useState<'basic' | 'education' | 'experience' | 'skills'>('basic')

  const handleSave = () => {
    setPerson(editData)
    setIsEditing(false)
  }

  const handleCancel = () => {
    setEditData(person)
    setIsEditing(false)
  }

  const addSkill = (skill: string) => {
    if (skill && !editData.skills.includes(skill)) {
      setEditData({ ...editData, skills: [...editData.skills, skill] })
    }
  }

  const removeSkill = (skill: string) => {
    setEditData({ ...editData, skills: editData.skills.filter(s => s !== skill) })
  }

  return (
    <div>
      <div className="page-header">
        <h2 className="page-title">👤 个人信息</h2>
        {!isEditing ? (
          <button
            onClick={() => setIsEditing(true)}
            style={{
              padding: '10px 20px',
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              color: 'white',
              border: 'none',
              borderRadius: '8px',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: '8px'
            }}
          >
            <Edit2 size={18} />
            编辑
          </button>
        ) : (
          <div style={{ display: 'flex', gap: '12px' }}>
            <button
              onClick={handleCancel}
              style={{
                padding: '10px 20px',
                background: '#f0f0f0',
                border: 'none',
                borderRadius: '8px',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '8px'
              }}
            >
              <X size={18} />
              取消
            </button>
            <button
              onClick={handleSave}
              style={{
                padding: '10px 20px',
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '8px'
              }}
            >
              <Save size={18} />
              保存
            </button>
          </div>
        )}
      </div>

      {/* 标签页 */}
      <div style={{
        display: 'flex',
        gap: '8px',
        marginBottom: '24px',
        borderBottom: '2px solid #e9ecef',
        paddingBottom: '12px'
      }}>
        {[
          { key: 'basic', label: '基本信息', icon: User },
          { key: 'education', label: '教育背景', icon: GraduationCap },
          { key: 'experience', label: '工作经历', icon: Briefcase },
          { key: 'skills', label: '技能证书', icon: Award }
        ].map(({ key, label, icon: Icon }) => (
          <button
            key={key}
            onClick={() => setActiveTab(key as any)}
            style={{
              padding: '10px 20px',
              background: activeTab === key ? 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' : 'transparent',
              color: activeTab === key ? 'white' : '#666',
              border: 'none',
              borderRadius: '8px',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              gap: '8px'
            }}
          >
            <Icon size={16} />
            {label}
          </button>
        ))}
      </div>

      {/* 基本信息 */}
      {activeTab === 'basic' && (
        <div className="card" style={{ maxWidth: '800px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '24px', marginBottom: '24px' }}>
            <div style={{
              width: '100px',
              height: '100px',
              borderRadius: '50%',
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: 'white',
              fontSize: '2rem'
            }}>
              {person.name[0]}
            </div>
            <div>
              {isEditing ? (
                <>
                  <input
                    type="text"
                    value={editData.name}
                    onChange={(e) => setEditData({ ...editData, name: e.target.value })}
                    style={{
                      fontSize: '1.5rem',
                      fontWeight: 600,
                      border: '1px solid #ddd',
                      borderRadius: '4px',
                      padding: '8px',
                      marginBottom: '8px',
                      width: '100%'
                    }}
                  />
                  <input
                    type="text"
                    value={editData.title}
                    onChange={(e) => setEditData({ ...editData, title: e.target.value })}
                    style={{
                      color: '#666',
                      border: '1px solid #ddd',
                      borderRadius: '4px',
                      padding: '6px',
                      width: '100%'
                    }}
                  />
                </>
              ) : (
                <>
                  <h2 style={{ margin: 0, marginBottom: '8px' }}>{person.name}</h2>
                  <p style={{ color: '#666', margin: 0 }}>{person.title}</p>
                </>
              )}
            </div>
          </div>

          <div style={{ display: 'grid', gap: '16px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
              <Mail size={20} color="#667eea" />
              {isEditing ? (
                <input
                  type="email"
                  value={editData.email}
                  onChange={(e) => setEditData({ ...editData, email: e.target.value })}
                  style={{ flex: 1, padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                />
              ) : (
                <span>{person.email}</span>
              )}
            </div>

            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
              <Phone size={20} color="#667eea" />
              {isEditing ? (
                <input
                  type="tel"
                  value={editData.phone}
                  onChange={(e) => setEditData({ ...editData, phone: e.target.value })}
                  style={{ flex: 1, padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                />
              ) : (
                <span>{person.phone}</span>
              )}
            </div>

            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
              <MapPin size={20} color="#667eea" />
              {isEditing ? (
                <input
                  type="text"
                  value={editData.location}
                  onChange={(e) => setEditData({ ...editData, location: e.target.value })}
                  style={{ flex: 1, padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                />
              ) : (
                <span>{person.location}</span>
              )}
            </div>

            <div>
              <h4 style={{ marginBottom: '8px' }}>个人简介</h4>
              {isEditing ? (
                <textarea
                  value={editData.bio}
                  onChange={(e) => setEditData({ ...editData, bio: e.target.value })}
                  rows={4}
                  style={{
                    width: '100%',
                    padding: '8px',
                    border: '1px solid #ddd',
                    borderRadius: '4px',
                    resize: 'vertical'
                  }}
                />
              ) : (
                <p style={{ color: '#666', lineHeight: 1.6 }}>{person.bio}</p>
              )}
            </div>
          </div>
        </div>
      )}

      {/* 教育背景 */}
      {activeTab === 'education' && (
        <div className="card">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
            <h3 style={{ margin: 0 }}>教育背景</h3>
            {isEditing && (
              <button
                onClick={() => {
                  const newEdu: Education = {
                    id: Date.now().toString(),
                    school: '',
                    degree: '',
                    field: '',
                    startYear: '',
                    endYear: ''
                  }
                  setEditData({ ...editData, education: [...editData.education, newEdu] })
                }}
                style={{
                  padding: '8px 16px',
                  background: '#667eea',
                  color: 'white',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px'
                }}
              >
                <Plus size={16} />
                添加
              </button>
            )}
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {(isEditing ? editData : person).education.map((edu) => (
              <div
                key={edu.id}
                style={{
                  padding: '16px',
                  background: '#f8f9fa',
                  borderRadius: '8px',
                  borderLeft: '4px solid #667eea'
                }}
              >
                {isEditing ? (
                  <div style={{ display: 'grid', gap: '12px' }}>
                    <input
                      type="text"
                      placeholder="学校"
                      value={edu.school}
                      onChange={(evt) => {
                        const updated = editData.education.map((item) =>
                          item.id === edu.id ? { ...item, school: evt.target.value } : item
                        )
                        setEditData({ ...editData, education: updated })
                      }}
                      style={{ padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                    />
                    <div style={{ display: 'flex', gap: '12px' }}>
                      <input
                        type="text"
                        placeholder="学位"
                        value={edu.degree}
                        onChange={(evt) => {
                          const updated = editData.education.map((item) =>
                            item.id === edu.id ? { ...item, degree: evt.target.value } : item
                          )
                          setEditData({ ...editData, education: updated })
                        }}
                        style={{ flex: 1, padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                      />
                      <input
                        type="text"
                        placeholder="专业"
                        value={edu.field}
                        onChange={(evt) => {
                          const updated = editData.education.map((item) =>
                            item.id === edu.id ? { ...item, field: evt.target.value } : item
                          )
                          setEditData({ ...editData, education: updated })
                        }}
                        style={{ flex: 1, padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                      />
                    </div>
                    <div style={{ display: 'flex', gap: '12px' }}>
                      <input
                        type="text"
                        placeholder="开始年份"
                        value={edu.startYear}
                        onChange={(evt) => {
                          const updated = editData.education.map((item) =>
                            item.id === edu.id ? { ...item, startYear: evt.target.value } : item
                          )
                          setEditData({ ...editData, education: updated })
                        }}
                        style={{ flex: 1, padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                      />
                      <input
                        type="text"
                        placeholder="结束年份"
                        value={edu.endYear}
                        onChange={(evt) => {
                          const updated = editData.education.map((item) =>
                            item.id === edu.id ? { ...item, endYear: evt.target.value } : item
                          )
                          setEditData({ ...editData, education: updated })
                        }}
                        style={{ flex: 1, padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                      />
                    </div>
                    <button
                      onClick={() => {
                        setEditData({
                          ...editData,
                          education: editData.education.filter((e) => e.id !== edu.id)
                        })
                      }}
                      style={{
                        padding: '6px 12px',
                        background: '#ef5350',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '6px',
                        justifyContent: 'center'
                      }}
                    >
                      <Trash2 size={14} />
                      删除
                    </button>
                  </div>
                ) : (
                  <>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                      <h4 style={{ margin: 0 }}>{edu.school}</h4>
                      <span style={{ color: '#666', fontSize: '0.9rem' }}>
                        {edu.startYear} - {edu.endYear}
                      </span>
                    </div>
                    <p style={{ margin: 0, color: '#667eea' }}>
                      {edu.degree} · {edu.field}
                    </p>
                  </>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 工作经历 */}
      {activeTab === 'experience' && (
        <div className="card">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
            <h3 style={{ margin: 0 }}>工作经历</h3>
            {isEditing && (
              <button
                onClick={() => {
                  const newExp: Experience = {
                    id: Date.now().toString(),
                    company: '',
                    position: '',
                    description: '',
                    startDate: '',
                    endDate: ''
                  }
                  setEditData({ ...editData, experience: [...editData.experience, newExp] })
                }}
                style={{
                  padding: '8px 16px',
                  background: '#667eea',
                  color: 'white',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px'
                }}
              >
                <Plus size={16} />
                添加
              </button>
            )}
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {(isEditing ? editData : person).experience.map((exp) => (
              <div
                key={exp.id}
                style={{
                  padding: '16px',
                  background: '#f8f9fa',
                  borderRadius: '8px',
                  borderLeft: '4px solid #11998e'
                }}
              >
                {isEditing ? (
                  <div style={{ display: 'grid', gap: '12px' }}>
                    <input
                      type="text"
                      placeholder="公司"
                      value={exp.company}
                      onChange={(evt) => {
                        const updated = editData.experience.map((item) =>
                          item.id === exp.id ? { ...item, company: evt.target.value } : item
                        )
                        setEditData({ ...editData, experience: updated })
                      }}
                      style={{ padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                    />
                    <input
                      type="text"
                      placeholder="职位"
                      value={exp.position}
                      onChange={(evt) => {
                        const updated = editData.experience.map((item) =>
                          item.id === exp.id ? { ...item, position: evt.target.value } : item
                        )
                        setEditData({ ...editData, experience: updated })
                      }}
                      style={{ padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                    />
                    <textarea
                      placeholder="工作描述"
                      value={exp.description}
                      onChange={(evt) => {
                        const updated = editData.experience.map((item) =>
                          item.id === exp.id ? { ...item, description: evt.target.value } : item
                        )
                        setEditData({ ...editData, experience: updated })
                      }}
                      rows={3}
                      style={{ padding: '8px', border: '1px solid #ddd', borderRadius: '4px', resize: 'vertical' }}
                    />
                    <div style={{ display: 'flex', gap: '12px' }}>
                      <input
                        type="text"
                        placeholder="开始时间"
                        value={exp.startDate}
                        onChange={(evt) => {
                          const updated = editData.experience.map((item) =>
                            item.id === exp.id ? { ...item, startDate: evt.target.value } : item
                          )
                          setEditData({ ...editData, experience: updated })
                        }}
                        style={{ flex: 1, padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                      />
                      <input
                        type="text"
                        placeholder="结束时间"
                        value={exp.endDate}
                        onChange={(evt) => {
                          const updated = editData.experience.map((item) =>
                            item.id === exp.id ? { ...item, endDate: evt.target.value } : item
                          )
                          setEditData({ ...editData, experience: updated })
                        }}
                        style={{ flex: 1, padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                      />
                    </div>
                    <button
                      onClick={() => {
                        setEditData({
                          ...editData,
                          experience: editData.experience.filter((e) => e.id !== exp.id)
                        })
                      }}
                      style={{
                        padding: '6px 12px',
                        background: '#ef5350',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer'
                      }}
                    >
                      <Trash2 size={14} /> 删除
                    </button>
                  </div>
                ) : (
                  <>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                      <h4 style={{ margin: 0 }}>{exp.company}</h4>
                      <span style={{ color: '#666', fontSize: '0.9rem' }}>
                        {exp.startDate} - {exp.endDate}
                      </span>
                    </div>
                    <p style={{ margin: '0 0 8px 0', color: '#11998e', fontWeight: 500 }}>
                      {exp.position}
                    </p>
                    <p style={{ margin: 0, color: '#666', fontSize: '0.9rem' }}>
                      {exp.description}
                    </p>
                  </>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 技能证书 */}
      {activeTab === 'skills' && (
        <div className="card">
          <h3 style={{ marginBottom: '20px' }}>技能与证书</h3>

          {/* 技能 */}
          <div style={{ marginBottom: '32px' }}>
            <h4 style={{ marginBottom: '16px' }}>专业技能</h4>
            {isEditing && (
              <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
                <input
                  type="text"
                  id="newSkill"
                  placeholder="添加技能"
                  style={{ flex: 1, padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                  onKeyPress={(e) => {
                    if (e.key === 'Enter') {
                      const input = e.target as HTMLInputElement
                      addSkill(input.value)
                      input.value = ''
                    }
                  }}
                />
                <button
                  onClick={() => {
                    const input = document.getElementById('newSkill') as HTMLInputElement
                    if (input.value) {
                      addSkill(input.value)
                      input.value = ''
                    }
                  }}
                  style={{
                    padding: '8px 16px',
                    background: '#667eea',
                    color: 'white',
                    border: 'none',
                    borderRadius: '6px',
                    cursor: 'pointer'
                  }}
                >
                  <Plus size={16} />
                </button>
              </div>
            )}

            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
              {(isEditing ? editData : person).skills.map((skill) => (
                <span
                  key={skill}
                  style={{
                    padding: '6px 12px',
                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    color: 'white',
                    borderRadius: '16px',
                    fontSize: '0.9rem',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px'
                  }}
                >
                  {skill}
                  {isEditing && (
                    <button
                      onClick={() => removeSkill(skill)}
                      style={{
                        background: 'none',
                        border: 'none',
                        color: 'white',
                        cursor: 'pointer',
                        padding: 0,
                        display: 'flex'
                      }}
                    >
                      <X size={14} />
                    </button>
                  )}
                </span>
              ))}
            </div>
          </div>

          {/* 证书 */}
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
              <h4 style={{ margin: 0 }}>证书</h4>
              {isEditing && (
                <button
                  onClick={() => {
                    const newCert: Certification = {
                      id: Date.now().toString(),
                      name: '',
                      issuer: '',
                      date: ''
                    }
                    setEditData({ ...editData, certifications: [...editData.certifications, newCert] })
                  }}
                  style={{
                    padding: '6px 12px',
                    background: '#667eea',
                    color: 'white',
                    border: 'none',
                    borderRadius: '6px',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px'
                  }}
                >
                  <Plus size={14} />
                  添加
                </button>
              )}
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              {(isEditing ? editData : person).certifications.map((cert) => (
                <div
                  key={cert.id}
                  style={{
                    padding: '12px 16px',
                    background: '#f8f9fa',
                    borderRadius: '8px',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center'
                  }}
                >
                  {isEditing ? (
                    <div style={{ display: 'grid', gap: '8px', width: '100%' }}>
                      <input
                        type="text"
                        placeholder="证书名称"
                        value={cert.name}
                        onChange={(evt) => {
                          const updated = editData.certifications.map((item) =>
                            item.id === cert.id ? { ...item, name: evt.target.value } : item
                          )
                          setEditData({ ...editData, certifications: updated })
                        }}
                        style={{ padding: '6px', border: '1px solid #ddd', borderRadius: '4px' }}
                      />
                      <div style={{ display: 'flex', gap: '8px' }}>
                        <input
                          type="text"
                          placeholder="颁发机构"
                          value={cert.issuer}
                          onChange={(evt) => {
                            const updated = editData.certifications.map((item) =>
                              item.id === cert.id ? { ...item, issuer: evt.target.value } : item
                            )
                            setEditData({ ...editData, certifications: updated })
                          }}
                          style={{ flex: 1, padding: '6px', border: '1px solid #ddd', borderRadius: '4px' }}
                        />
                        <input
                          type="text"
                          placeholder="获得时间"
                          value={cert.date}
                          onChange={(evt) => {
                            const updated = editData.certifications.map((item) =>
                              item.id === cert.id ? { ...item, date: evt.target.value } : item
                            )
                            setEditData({ ...editData, certifications: updated })
                          }}
                          style={{ width: '120px', padding: '6px', border: '1px solid #ddd', borderRadius: '4px' }}
                        />
                      </div>
                      <button
                        onClick={() => {
                          setEditData({
                            ...editData,
                            certifications: editData.certifications.filter((c) => c.id !== cert.id)
                          })
                        }}
                        style={{
                          padding: '4px 8px',
                          background: '#ef5350',
                          color: 'white',
                          border: 'none',
                          borderRadius: '4px',
                          cursor: 'pointer'
                        }}
                      >
                        <Trash2 size={12} /> 删除
                      </button>
                    </div>
                  ) : (
                    <>
                      <div>
                        <div style={{ fontWeight: 500 }}>{cert.name}</div>
                        <div style={{ fontSize: '0.85rem', color: '#666' }}>
                          {cert.issuer} · {cert.date}
                        </div>
                      </div>
                      <Award size={20} color="#667eea" />
                    </>
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
