import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'

// SVG图标组件
const ChevronLeftIcon = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <polyline points="15 18 9 12 15 6"></polyline>
  </svg>
)

const ChevronRightIcon = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <polyline points="9 18 15 12 9 6"></polyline>
  </svg>
)

const PlusIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <line x1="12" y1="5" x2="12" y2="19"></line>
    <line x1="5" y1="12" x2="19" y2="12"></line>
  </svg>
)

export function Calendar() {
  const navigate = useNavigate()
  const [currentDate, setCurrentDate] = useState(new Date())
  const [events, setEvents] = useState<any[]>([])
  const [stats, setStats] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [showModal, setShowModal] = useState(false)
  const [showDetailModal, setShowDetailModal] = useState(false)
  const [selectedEvent, setSelectedEvent] = useState<any>(null)
  const [viewMode, setViewMode] = useState<'month' | 'week' | 'day'>('month')
  
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    start_time: '',
    end_time: '',
    all_day: false,
    location: '',
    category: 'default',
    color: '#667eea',
    reminder_minutes: 15
  })

  useEffect(() => {
    loadData()
  }, [currentDate])

  const loadData = async () => {
    try {
      const year = currentDate.getFullYear()
      const month = currentDate.getMonth()
      
      const endDate = new Date(year, month + 1, 0)
      
      // 使用本地时间格式，避免时区偏差
      const startStr = `${year}-${String(month + 1).padStart(2, '0')}-01`
      const endStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(endDate.getDate()).padStart(2, '0')}`
      
      const [eventsRes, statsRes] = await Promise.all([
        fetch(`/api/calendar/events?start=${startStr}&end=${endStr}`).then(r => r.json()),
        fetch('/api/calendar/stats').then(r => r.json())
      ])
      
      if (eventsRes.success) setEvents(eventsRes.events || [])
      if (statsRes.success) setStats(statsRes.stats)
    } catch (e) {
      console.error(e)
    } finally {
      setLoading(false)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    
    try {
      const res = await fetch('/api/calendar/events', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      })
      
      const data = await res.json()
      if (data.success) {
        setShowModal(false)
        setFormData({
          title: '',
          description: '',
          start_time: '',
          end_time: '',
          all_day: false,
          location: '',
          category: 'default',
          color: '#667eea',
          reminder_minutes: 15
        })
        loadData()
      }
    } catch (e) {
      console.error(e)
    }
  }

  const handlePrevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))
  }

  const handleNextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))
  }

  const handleToday = () => {
    setCurrentDate(new Date())
    setViewMode('day')  // 切换到日视图
  }

  // 生成周视图日期
  const generateWeekDays = () => {
    const year = currentDate.getFullYear()
    const month = currentDate.getMonth()
    const date = currentDate.getDate()
    
    const current = new Date(year, month, date)
    const dayOfWeek = current.getDay()
    
    // 获取本周第一天（周日）
    const startOfWeek = new Date(current)
    startOfWeek.setDate(date - dayOfWeek)
    
    const days = []
    for (let i = 0; i < 7; i++) {
      const day = new Date(startOfWeek)
      day.setDate(startOfWeek.getDate() + i)
      days.push(day)
    }
    
    return days
  }

  const generateCalendarDays = () => {
    const year = currentDate.getFullYear()
    const month = currentDate.getMonth()
    
    const firstDay = new Date(year, month, 1)
    const lastDay = new Date(year, month + 1, 0)
    
    const startDayOfWeek = firstDay.getDay()
    const daysInMonth = lastDay.getDate()
    
    const days = []
    
    for (let i = 0; i < startDayOfWeek; i++) {
      days.push(null)
    }
    
    for (let i = 1; i <= daysInMonth; i++) {
      days.push(new Date(year, month, i))
    }
    
    return days
  }

  const getEventsForDate = (date: Date) => {
    if (!date) return []
    // 使用本地时间格式，避免时区偏差
    const dateStr = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
    return events.filter(e => e.start_time?.startsWith(dateStr))
  }

  const isToday = (date: Date) => {
    if (!date) return false
    const today = new Date()
    return date.toDateString() === today.toDateString()
  }

  const weekDays = ['日', '一', '二', '三', '四', '五', '六']
  const calendarDays = generateCalendarDays()
  const monthNames = ['一月', '二月', '三月', '四月', '五月', '六月', '七月', '八月', '九月', '十月', '十一月', '十二月']

  if (loading) return <div className="loading">加载中...</div>

  return (
    <div>
      <div className="page-header">
        <h2 className="page-title">📅 日历</h2>
        <div style={{ display: 'flex', gap: '12px' }}>
          <button className="btn btn-secondary" onClick={() => navigate('/calendar-settings')}>
            ⚙️ 同步设置
          </button>
          <button className="btn btn-success" onClick={() => setShowModal(true)}>
            <PlusIcon /> 新建事件
          </button>
        </div>
      </div>

      {stats && (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))', gap: '12px', marginBottom: '20px' }}>
          <div className="stat-card blue" style={{ padding: '12px' }}>
            <div className="stat-icon" style={{ width: '40px', height: '40px', fontSize: '1.1rem' }}>📅</div>
            <div className="stat-info">
              <h3 style={{ fontSize: '1.3rem' }}>{stats.today}</h3>
              <p style={{ fontSize: '0.75rem' }}>今日事件</p>
            </div>
          </div>
          <div className="stat-card purple" style={{ padding: '12px' }}>
            <div className="stat-icon" style={{ width: '40px', height: '40px', fontSize: '1.1rem' }}>📊</div>
            <div className="stat-info">
              <h3 style={{ fontSize: '1.3rem' }}>{stats.week}</h3>
              <p style={{ fontSize: '0.75rem' }}>本周事件</p>
            </div>
          </div>
          <div className="stat-card green" style={{ padding: '12px' }}>
            <div className="stat-icon" style={{ width: '40px', height: '40px', fontSize: '1.1rem' }}>📈</div>
            <div className="stat-info">
              <h3 style={{ fontSize: '1.3rem' }}>{stats.month}</h3>
              <p style={{ fontSize: '0.75rem' }}>本月事件</p>
            </div>
          </div>
          <div className="stat-card orange" style={{ padding: '12px' }}>
            <div className="stat-icon" style={{ width: '40px', height: '40px', fontSize: '1.1rem' }}>⏰</div>
            <div className="stat-info">
              <h3 style={{ fontSize: '1.3rem' }}>{stats.upcoming}</h3>
              <p style={{ fontSize: '0.75rem' }}>待处理</p>
            </div>
          </div>
        </div>
      )}

      <div className="card" style={{ marginBottom: '16px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <button className="btn btn-secondary" onClick={handlePrevMonth}>
              <ChevronLeftIcon />
            </button>
            <h3 style={{ margin: 0, minWidth: '150px', textAlign: 'center' }}>
              {currentDate.getFullYear()}年 {monthNames[currentDate.getMonth()]}
            </h3>
            <button className="btn btn-secondary" onClick={handleNextMonth}>
              <ChevronRightIcon />
            </button>
          </div>
          <div style={{ display: 'flex', gap: '8px' }}>
            <button className="btn btn-secondary" onClick={handleToday}>今天</button>
            <button className={`btn ${viewMode === 'month' ? 'btn-primary' : 'btn-secondary'}`} onClick={() => setViewMode('month')}>月</button>
            <button className={`btn ${viewMode === 'week' ? 'btn-primary' : 'btn-secondary'}`} onClick={() => setViewMode('week')}>周</button>
          </div>
        </div>
      </div>

      {viewMode === 'month' && (
        <div className="card" style={{ padding: '16px' }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '4px', marginBottom: '8px' }}>
            {weekDays.map(day => (
              <div key={day} style={{ textAlign: 'center', fontWeight: 600, padding: '8px', color: '#666' }}>{day}</div>
            ))}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '4px' }}>
            {calendarDays.map((date, index) => {
              if (!date) return <div key={`empty-${index}`} style={{ minHeight: '80px', background: '#f8f9fa', borderRadius: '4px' }} />
              
              const dayEvents = getEventsForDate(date)
              const today = isToday(date)
              
              return (
                <div 
                  key={date.toISOString()} 
                  style={{ 
                    minHeight: '80px', 
                    padding: '8px',
                    background: today ? '#e3f2fd' : 'white',
                    border: today ? '2px solid #2196f3' : '1px solid #e0e0e0',
                    borderRadius: '4px',
                    cursor: 'pointer'
                  }}
                  onClick={() => {
                    setFormData(prev => ({ ...prev, start_time: date.toISOString().slice(0, 16) }))
                    setShowModal(true)
                  }}
                >
                  <div style={{ fontWeight: today ? 700 : 500, color: today ? '#2196f3' : '#333', marginBottom: '4px' }}>
                    {date.getDate()}
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                    {dayEvents.map((event, i) => (
                      <div 
                        key={i} 
                        style={{
                          fontSize: '0.8rem',
                          fontWeight: 600,
                          padding: '4px 6px',
                          background: event.color || '#667eea',
                          color: 'white',
                          borderRadius: '6px',
                          overflow: 'hidden',
                          textOverflow: 'ellipsis',
                          whiteSpace: 'nowrap',
                          boxShadow: '0 2px 4px rgba(0,0,0,0.2)',
                          border: event.is_subscribed || event.source?.includes('订阅') ? '3px solid #ff1744' : '2px solid transparent',
                          transform: event.is_subscribed || event.source?.includes('订阅') ? 'scale(1.02)' : 'none',
                          transition: 'all 0.2s',
                          cursor: 'pointer'
                        }} 
                        title={event.title + (event.is_subscribed || event.source?.includes('订阅') ? ' [订阅]' : '')}
                        onClick={(e) => {
                          e.stopPropagation();
                          setSelectedEvent(event);
                          setShowDetailModal(true);
                        }}
                      >
                        <span style={{ marginRight: '4px' }}>
                          {event.is_subscribed || event.source?.includes('订阅') ? '🔔 ' : '📅 '}
                        </span>
                        {event.title}
                      </div>
                    ))}
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* 周视图 */}
      {viewMode === 'week' && (
        <div className="card" style={{ padding: '16px' }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '4px', marginBottom: '8px' }}>
            {weekDays.map(day => (
              <div key={day} style={{ textAlign: 'center', fontWeight: 600, padding: '8px', color: '#666' }}>{day}</div>
            ))}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '4px' }}>
            {generateWeekDays().map((date, index) => {
              const dayEvents = getEventsForDate(date)
              const today = isToday(date)
              
              return (
                <div 
                  key={index} 
                  style={{ 
                    minHeight: '200px', 
                    padding: '8px',
                    background: today ? '#e3f2fd' : 'white',
                    border: today ? '2px solid #2196f3' : '1px solid #e0e0e0',
                    borderRadius: '4px',
                    cursor: 'pointer'
                  }}
                  onClick={() => {
                    setFormData(prev => ({ ...prev, start_time: date.toISOString().slice(0, 16) }))
                    setShowModal(true)
                  }}
                >
                  <div style={{ fontWeight: today ? 700 : 500, color: today ? '#2196f3' : '#333', marginBottom: '8px', textAlign: 'center' }}>
                    {date.getMonth() + 1}/{date.getDate()}
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                    {dayEvents.map((event, i) => (
                      <div 
                        key={i} 
                        style={{
                          fontSize: '0.75rem',
                          fontWeight: 600,
                          padding: '4px 6px',
                          background: event.color || '#667eea',
                          color: 'white',
                          borderRadius: '6px',
                          overflow: 'hidden',
                          textOverflow: 'ellipsis',
                          whiteSpace: 'nowrap',
                          boxShadow: '0 2px 4px rgba(0,0,0,0.2)',
                          cursor: 'pointer'
                        }}
                        onClick={(e) => {
                          e.stopPropagation();
                          setSelectedEvent(event);
                          setShowDetailModal(true);
                        }}
                      >
                        {event.title}
                      </div>
                    ))}
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* 日视图（今日） */}
      {viewMode === 'day' && (
        <div className="card" style={{ padding: '16px' }}>
          <div style={{ textAlign: 'center', marginBottom: '16px' }}>
            <h3>{currentDate.getFullYear()}年{currentDate.getMonth() + 1}月{currentDate.getDate()}日</h3>
          </div>
          <div style={{ minHeight: '400px', padding: '16px', background: '#f8f9fa', borderRadius: '8px' }}>
            {(() => {
              const dayEvents = getEventsForDate(currentDate)
              return dayEvents.length > 0 ? (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                  {dayEvents.map((event, i) => (
                    <div 
                      key={i} 
                      style={{
                        padding: '16px',
                        background: event.color || '#667eea',
                        color: 'white',
                        borderRadius: '8px',
                        boxShadow: '0 2px 8px rgba(0,0,0,0.2)',
                        cursor: 'pointer'
                      }}
                      onClick={() => {
                        setSelectedEvent(event);
                        setShowDetailModal(true);
                      }}
                    >
                      <div style={{ fontSize: '1.1rem', fontWeight: 600, marginBottom: '8px' }}>
                        {event.is_subscribed || event.source?.includes('订阅') ? '🔔 ' : '📅 '}
                        {event.title}
                      </div>
                      {event.start_time && (
                        <div style={{ fontSize: '0.9rem', opacity: 0.9 }}>
                          ⏰ {new Date(event.start_time).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })}
                          {event.end_time && ` - ${new Date(event.end_time).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })}`}
                        </div>
                      )}
                      {event.location && (
                        <div style={{ fontSize: '0.9rem', opacity: 0.9, marginTop: '4px' }}>
                          📍 {event.location}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              ) : (
                <div style={{ textAlign: 'center', color: '#999', padding: '40px' }}>
                  <div style={{ fontSize: '3rem', marginBottom: '16px' }}>📅</div>
                  <p>今日暂无事件</p>
                </div>
              )
            })()}
          </div>
        </div>
      )}

      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal" onClick={e => e.stopPropagation()} style={{ maxWidth: '500px' }}>
            <h3><PlusIcon /> 新建事件</h3>
            <form onSubmit={handleSubmit} style={{ marginTop: '16px' }}>
              <div style={{ marginBottom: '12px' }}>
                <label>标题 *</label>
                <input type="text" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} placeholder="事件标题" required />
              </div>
              <div style={{ marginBottom: '12px' }}>
                <label>描述</label>
                <textarea value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} placeholder="事件描述..." rows={2} />
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', marginBottom: '12px' }}>
                <div>
                  <label>开始时间 *</label>
                  <input type="datetime-local" value={formData.start_time} onChange={e => setFormData({...formData, start_time: e.target.value})} required />
                </div>
                <div>
                  <label>结束时间</label>
                  <input type="datetime-local" value={formData.end_time} onChange={e => setFormData({...formData, end_time: e.target.value})} />
                </div>
              </div>
              <div style={{ marginBottom: '12px' }}>
                <label>地点</label>
                <input type="text" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} placeholder="事件地点" />
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', marginBottom: '12px' }}>
                <div>
                  <label>分类</label>
                  <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                    <option value="default">默认</option>
                    <option value="work">工作</option>
                    <option value="personal">个人</option>
                    <option value="meeting">会议</option>
                    <option value="reminder">提醒</option>
                  </select>
                </div>
                <div>
                  <label>颜色</label>
                  <input type="color" value={formData.color} onChange={e => setFormData({...formData, color: e.target.value})} style={{ width: '100%', height: '38px' }} />
                </div>
              </div>
              <div style={{ marginBottom: '16px' }}>
                <label><input type="checkbox" checked={formData.all_day} onChange={e => setFormData({...formData, all_day: e.target.checked})} /> 全天事件</label>
              </div>
              <div className="modal-actions">
                <button type="button" className="btn btn-secondary" onClick={() => setShowModal(false)}>取消</button>
                <button type="submit" className="btn btn-success">创建事件</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* 事件详情弹窗 */}
      {showDetailModal && selectedEvent && (
        <div className="modal-overlay" onClick={() => setShowDetailModal(false)}>
          <div className="modal" onClick={e => e.stopPropagation()} style={{ maxWidth: '600px', maxHeight: '80vh', overflow: 'auto' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
              <h3 style={{ margin: 0 }}>📅 事件详情</h3>
              <div style={{ display: 'flex', gap: '8px' }}>
                <button 
                  className="btn btn-danger" 
                  onClick={async () => {
                    if (confirm('确定要删除这个日程吗？')) {
                      try {
                        const res = await fetch(`/api/calendar/events/${selectedEvent.id}`, { method: 'DELETE' })
                        const data = await res.json()
                        if (data.success) {
                          alert('删除成功！')
                          setShowDetailModal(false)
                          loadData() // 刷新日历
                        } else {
                          alert('删除失败：' + (data.error || '未知错误'))
                        }
                      } catch (e) {
                        alert('删除失败：' + e)
                      }
                    }
                  }}
                >
                  🗑️ 删除
                </button>
                <button className="btn btn-secondary" onClick={() => setShowDetailModal(false)}>关闭</button>
              </div>
            </div>
            
            <div style={{ marginBottom: '20px' }}>
              <h4 style={{ color: selectedEvent.color || '#667eea', marginBottom: '16px' }}>
                {selectedEvent.title}
              </h4>
              
              {/* 时间信息 */}
              <div style={{ background: '#f5f5f5', padding: '16px', borderRadius: '8px', marginBottom: '16px' }}>
                <h5 style={{ margin: '0 0 12px 0' }}>⏰ 时间信息</h5>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                  <div>
                    <label style={{ color: '#666', fontSize: '0.85rem' }}>开始时间</label>
                    <div style={{ fontWeight: 500 }}>
                      {selectedEvent.start_time ? new Date(selectedEvent.start_time).toLocaleString('zh-CN') : '未设置'}
                    </div>
                  </div>
                  <div>
                    <label style={{ color: '#666', fontSize: '0.85rem' }}>结束时间</label>
                    <div style={{ fontWeight: 500 }}>
                      {selectedEvent.end_time ? new Date(selectedEvent.end_time).toLocaleString('zh-CN') : '未设置'}
                    </div>
                  </div>
                </div>
                {selectedEvent.is_all_day && (
                  <div style={{ marginTop: '8px', color: '#2196f3', fontWeight: 500 }}>📌 全天事件</div>
                )}
              </div>
              
              {/* 地点 */}
              {selectedEvent.location && (
                <div style={{ marginBottom: '16px' }}>
                  <h5 style={{ margin: '0 0 8px 0' }}>📍 地点</h5>
                  <div style={{ padding: '12px', background: '#e3f2fd', borderRadius: '6px' }}>
                    {selectedEvent.location}
                  </div>
                </div>
              )}
              
              {/* 参与人员 */}
              {selectedEvent.participants && (
                <div style={{ marginBottom: '16px' }}>
                  <h5 style={{ margin: '0 0 8px 0' }}>👥 参与人员</h5>
                  <div style={{ padding: '12px', background: '#f3e5f5', borderRadius: '6px' }}>
                    {selectedEvent.participants}
                  </div>
                </div>
              )}
              
              {/* 描述 */}
              {selectedEvent.description && (
                <div style={{ marginBottom: '16px' }}>
                  <h5 style={{ margin: '0 0 8px 0' }}>📝 详细描述</h5>
                  <div style={{ padding: '12px', background: '#f5f5f5', borderRadius: '6px', whiteSpace: 'pre-wrap' }}>
                    {selectedEvent.description}
                  </div>
                </div>
              )}
              
              {/* 关联会议纪要 */}
              {selectedEvent.meeting_minutes_id && (
                <div style={{ marginBottom: '16px' }}>
                  <h5 style={{ margin: '0 0 8px 0' }}>📋 关联会议纪要</h5>
                  <div style={{ padding: '12px', background: '#fff3e0', borderRadius: '6px' }}>
                    <a href={`/meetings/${selectedEvent.meeting_minutes_id}`} style={{ color: '#e65100' }}>
                      查看会议纪要 #{selectedEvent.meeting_minutes_id}
                    </a>
                  </div>
                </div>
              )}
              
              {/* 重复规则 */}
              {selectedEvent.recurrence && (
                <div style={{ marginBottom: '16px' }}>
                  <h5 style={{ margin: '0 0 8px 0' }}>🔄 重复规则</h5>
                  <div style={{ padding: '12px', background: '#e8f5e9', borderRadius: '6px' }}>
                    {selectedEvent.recurrence}
                  </div>
                </div>
              )}
              
              {/* 其他信息 */}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', fontSize: '0.85rem', color: '#666' }}>
                {selectedEvent.category && (
                  <div>
                    <label>分类:</label> {selectedEvent.category}
                  </div>
                )}
                {selectedEvent.reminder_minutes && (
                  <div>
                    <label>提前提醒:</label> {selectedEvent.reminder_minutes}分钟
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
