import { useState, useEffect, useRef, useCallback } from 'react'
import ReactMarkdown from 'react-markdown'
import { PrismLight as SyntaxHighlighter } from 'react-syntax-highlighter'
import typescript from 'react-syntax-highlighter/dist/esm/languages/prism/typescript'
import javascript from 'react-syntax-highlighter/dist/esm/languages/prism/javascript'
import python from 'react-syntax-highlighter/dist/esm/languages/prism/python'
import bash from 'react-syntax-highlighter/dist/esm/languages/prism/bash'
import json from 'react-syntax-highlighter/dist/esm/languages/prism/json'
import css from 'react-syntax-highlighter/dist/esm/languages/prism/css'
import jsx from 'react-syntax-highlighter/dist/esm/languages/prism/jsx'
import tsx from 'react-syntax-highlighter/dist/esm/languages/prism/tsx'
import yaml from 'react-syntax-highlighter/dist/esm/languages/prism/yaml'
import sql from 'react-syntax-highlighter/dist/esm/languages/prism/sql'
import oneDark from 'react-syntax-highlighter/dist/esm/styles/prism/one-dark'
import { Send, Loader2, Trash2, Copy, Check, Bot, User, Sparkles, Clock } from 'lucide-react'

// 注册语言高亮
SyntaxHighlighter.registerLanguage('typescript', typescript)
SyntaxHighlighter.registerLanguage('javascript', javascript)
SyntaxHighlighter.registerLanguage('python', python)
SyntaxHighlighter.registerLanguage('bash', bash)
SyntaxHighlighter.registerLanguage('json', json)
SyntaxHighlighter.registerLanguage('css', css)
SyntaxHighlighter.registerLanguage('jsx', jsx)
SyntaxHighlighter.registerLanguage('tsx', tsx)
SyntaxHighlighter.registerLanguage('yaml', yaml)
SyntaxHighlighter.registerLanguage('sql', sql)

// 消息类型定义
interface Message {
  id: number
  role: 'user' | 'assistant' | 'system'
  content: string
  timestamp: string
  model?: string
  tokens?: number
}

// 会话类型定义
interface Conversation {
  id: string
  title: string
  lastMessage: string
  timestamp: string
  messageCount: number
}

// 代码块组件属性
interface CodeBlockProps {
  node?: any
  inline?: boolean
  className?: string
  children: React.ReactNode
}

// 自定义代码块组件
function CodeBlock({ node, inline, className, children, ...props }: CodeBlockProps) {
  const [copied, setCopied] = useState(false)
  const match = /language-(\w+)/.exec(className || '')
  const language = match ? match[1] : 'text'

  const handleCopy = async () => {
    const text = String(children).replace(/\n$/, '')
    await navigator.clipboard.writeText(text)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  if (inline) {
    return (
      <code
        className={className}
        style={{
          backgroundColor: 'rgba(110, 118, 129, 0.4)',
          padding: '0.2em 0.4em',
          borderRadius: '6px',
          fontSize: '85%',
          fontFamily: 'ui-monospace, SFMono-Regular, "SF Mono", Consolas, monospace'
        }}
        {...props}
      >
        {children}
      </code>
    )
  }

  return (
    <div style={{ position: 'relative', margin: '16px 0' }}>
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '8px 12px',
          backgroundColor: '#161b22',
          borderRadius: '8px 8px 0 0',
          borderBottom: '1px solid #30363d'
        }}
      >
        <span style={{ color: '#8b949e', fontSize: '12px', textTransform: 'uppercase' }}>
          {language}
        </span>
        <button
          onClick={handleCopy}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '4px',
            background: 'transparent',
            border: 'none',
            color: copied ? '#238636' : '#8b949e',
            cursor: 'pointer',
            fontSize: '12px'
          }}
        >
          {copied ? <Check size={14} /> : <Copy size={14} />}
          {copied ? '已复制' : '复制'}
        </button>
      </div>
      <SyntaxHighlighter
        style={oneDark as any}
        language={language}
        PreTag="div"
        customStyle={{
          margin: 0,
          borderRadius: '0 0 8px 8px',
          fontSize: '14px'
        }}
        {...props}
      >
        {String(children).replace(/\n$/, '')}
      </SyntaxHighlighter>
    </div>
  )
}

// 消息组件
function ChatMessage({ message, index }: { message: Message; index: number }) {
  const isUser = message.role === 'user'
  const isAssistant = message.role === 'assistant'

  return (
    <div
      style={{
        display: 'flex',
        justifyContent: isUser ? 'flex-end' : 'flex-start',
        marginBottom: '20px',
        animation: 'fadeIn 0.3s ease-out'
      }}
    >
      <div
        style={{
          display: 'flex',
          gap: '12px',
          maxWidth: '85%',
          flexDirection: isUser ? 'row-reverse' : 'row'
        }}
      >
        {/* 头像 */}
        <div
          style={{
            width: '36px',
            height: '36px',
            borderRadius: '50%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            background: isUser
              ? 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
              : 'linear-gradient(135deg, #11998e 0%, #38ef7d 100%)',
            flexShrink: 0
          }}
        >
          {isUser ? <User size={18} color="white" /> : <Bot size={18} color="white" />}
        </div>

        {/* 消息内容 */}
        <div style={{ flex: 1 }}>
          <div
            style={{
              padding: '12px 16px',
              borderRadius: isUser ? '16px 16px 4px 16px' : '16px 16px 16px 4px',
              background: isUser
                ? 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
                : 'white',
              color: isUser ? 'white' : '#333',
              boxShadow: '0 2px 12px rgba(0,0,0,0.08)',
              lineHeight: '1.6'
            }}
          >
            {isUser ? (
              <div style={{ whiteSpace: 'pre-wrap' }}>{message.content}</div>
            ) : (
              <ReactMarkdown
                components={{
                  code: CodeBlock as any,
                  p: ({ children }: any) => <p style={{ margin: '0 0 12px 0' }}>{children}</p>,
                  h1: ({ children }: any) => <h1 style={{ margin: '16px 0 12px 0', fontSize: '1.5em' }}>{children}</h1>,
                  h2: ({ children }: any) => <h2 style={{ margin: '14px 0 10px 0', fontSize: '1.3em' }}>{children}</h2>,
                  h3: ({ children }: any) => <h3 style={{ margin: '12px 0 8px 0', fontSize: '1.1em' }}>{children}</h3>,
                  ul: ({ children }: any) => <ul style={{ margin: '8px 0', paddingLeft: '20px' }}>{children}</ul>,
                  ol: ({ children }: any) => <ol style={{ margin: '8px 0', paddingLeft: '20px' }}>{children}</ol>,
                  li: ({ children }: any) => <li style={{ margin: '4px 0' }}>{children}</li>,
                  blockquote: ({ children }: any) => (
                    <blockquote
                      style={{
                        margin: '12px 0',
                        padding: '8px 16px',
                        borderLeft: '4px solid #667eea',
                        background: 'rgba(102, 126, 234, 0.1)',
                        borderRadius: '0 8px 8px 0'
                      }}
                    >
                      {children}
                    </blockquote>
                  ),
                  a: ({ href, children }: any) => (
                    <a href={href} style={{ color: isUser ? '#a5b4fc' : '#667eea', textDecoration: 'none' }}>
                      {children}
                    </a>
                  ),
                  table: ({ children }: any) => (
                    <table style={{ width: '100%', borderCollapse: 'collapse', margin: '12px 0' }}>
                      {children}
                    </table>
                  ),
                  thead: ({ children }: any) => <thead style={{ background: 'rgba(0,0,0,0.05)' }}>{children}</thead>,
                  th: ({ children }: any) => (
                    <th style={{ padding: '8px 12px', border: '1px solid #e1e4e8', textAlign: 'left' }}>
                      {children}
                    </th>
                  ),
                  td: ({ children }: any) => (
                    <td style={{ padding: '8px 12px', border: '1px solid #e1e4e8' }}>{children}</td>
                  )
                }}
              >
                {message.content}
              </ReactMarkdown>
            )}
          </div>

          {/* 消息元信息 */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              marginTop: '4px',
              fontSize: '11px',
              color: '#8b949e',
              justifyContent: isUser ? 'flex-end' : 'flex-start'
            }}
          >
            <Clock size={10} />
            <span>{new Date(message.timestamp).toLocaleTimeString()}</span>
            {message.model && <span>· {message.model}</span>}
            {message.tokens && <span>· {message.tokens} tokens</span>}
          </div>
        </div>
      </div>
    </div>
  )
}

// 加载指示器组件
