import { useState, useEffect } from 'react'
import { Activity, Cpu, HardDrive, Wifi, Server, RefreshCw } from 'lucide-react'

interface MacMiniStats {
  system: {
    platform: string
    processor: string
    hostname: string
    boot_time: string
  }
  cpu: {
    percent: number
    count: number
    frequency: {
      current: number
      min: number
      max: number
    }
  }
  memory: {
    total: number
    available: number
    percent: number
    used: number
    free: number
  }
  disk: {
    total: number
    used: number
    free: number
    percent: number
  }
  network: {
    bytes_sent: number
    bytes_recv: number
    packets_sent: number
    packets_recv: number
  }
  timestamp: string
}

// Mac Mini监控API - 使用相对路径通过Nginx代理
const MACMINI_API_URL = ''

export function MacMiniMonitor() {
  const [stats, setStats] = useState<MacMiniStats | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [lastUpdate, setLastUpdate] = useState<Date | null>(null)

  const loadStats = async () => {
    try {
      setLoading(true)
      setError('')
      
      // 注意：由于跨域限制，需要通过代理或直接访问
      const res = await fetch(`${MACMINI_API_URL}/api/macmini/stats`, {
        mode: 'cors',
        headers: {
          'Accept': 'application/json'
        }
      })
      
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}`)
      }
      
      const data = await res.json()
      
      if (data.success) {
        setStats(data)
        setLastUpdate(new Date())
      } else {
        setError(data.error || '获取数据失败')
      }
    } catch (e: any) {
      setError(`无法连接到Mac Mini监控服务: ${e.message}`)
      console.error('Mac Mini监控错误:', e)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadStats()
    // 每30秒自动刷新
    const interval = setInterval(loadStats, 30000)
    return () => clearInterval(interval)
  }, [])

  const formatBytes = (bytes: number) => {
    if (bytes === 0) return '0 B'
    const k = 1024
    const sizes = ['B', 'KB', 'MB', 'GB', 'TB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
  }

  const formatDuration = (bootTime: string) => {
    const boot = new Date(bootTime)
    const now = new Date()
    const diff = now.getTime() - boot.getTime()
    const days = Math.floor(diff / (1000 * 60 * 60 * 24))
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60))
    return `${days}天 ${hours}小时`
  }

  if (loading && !stats) {
    return (
      <div className="page-container">
        <div className="loading">加载Mac Mini监控数据...</div>
      </div>
    )
  }

  if (error && !stats) {
    return (
      <div className="page-container">
        <div className="page-header">
          <h2 className="page-title">🖥️ Mac Mini 监控</h2>
        </div>
        <div className="card" style={{ textAlign: 'center', padding: '40px' }}>
          <Server size={64} color="#999" style={{ marginBottom: '16px' }} />
          <h3 style={{ color: '#c62828', marginBottom: '12px' }}>连接失败</h3>
          <p style={{ color: '#666', marginBottom: '20px' }}>{error}</p>
          <p style={{ fontSize: '0.9rem', color: '#888', marginBottom: '20px' }}>
            请确保Mac Mini上已启动监控服务：<br/>
            <code style={{ background: '#f5f5f5', padding: '4px 8px', borderRadius: '4px' }}>
              python3 ~/.openclaw/workspace/scripts/macmini_monitor.py
            </code>
          </p>
          <button className="btn btn-primary" onClick={loadStats}>
            <RefreshCw size={16} style={{ marginRight: '8px' }} />
            重试连接
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <h2 className="page-title">🖥️ Mac Mini 监控</h2>
        <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
          {lastUpdate && (
            <span style={{ color: '#666', fontSize: '0.9rem' }}>
              最后更新: {lastUpdate.toLocaleTimeString()}
            </span>
          )}
          <button 
            className="btn btn-secondary" 
            onClick={loadStats}
            disabled={loading}
          >
            <RefreshCw size={16} style={{ marginRight: '8px', animation: loading ? 'spin 1s linear infinite' : 'none' }} />
            刷新
          </button>
        </div>
      </div>

      {stats && (
        <>
          {/* 系统信息 */}
          <div className="card" style={{ marginBottom: '24px' }}>
            <h3 style={{ marginBottom: '16px' }}>系统信息</h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '16px' }}>
              <div>
                <div style={{ fontSize: '0.85rem', color: '#666' }}>主机名</div>
                <div style={{ fontSize: '1.1rem', fontWeight: 600 }}>{stats.system.hostname}</div>
              </div>
              <div>
                <div style={{ fontSize: '0.85rem', color: '#666' }}>平台</div>
                <div style={{ fontSize: '1.1rem' }}>{stats.system.platform}</div>
              </div>
              <div>
                <div style={{ fontSize: '0.85rem', color: '#666' }}>处理器</div>
                <div style={{ fontSize: '1.1rem' }}>{stats.system.processor}</div>
              </div>
              <div>
                <div style={{ fontSize: '0.85rem', color: '#666' }}>运行时间</div>
                <div style={{ fontSize: '1.1rem', color: '#28a745' }}>{formatDuration(stats.system.boot_time)}</div>
              </div>
            </div>
          </div>

          {/* 资源统计 */}
          <div className="stats-grid" style={{ marginBottom: '24px' }}>
            {/* CPU */}
            <div className="stat-card">
              <div className="stat-icon" style={{ background: '#667eea20', color: '#667eea' }}>
                <Cpu size={24} />
              </div>
              <div className="stat-value">{stats.cpu.percent.toFixed(1)}%</div>
              <div className="stat-label">CPU使用率 ({stats.cpu.count}核)</div>
              <div style={{ marginTop: '8px', height: '6px', background: '#e0e0e0', borderRadius: '3px', overflow: 'hidden' }}>
                <div style={{ width: `${stats.cpu.percent}%`, height: '100%', background: stats.cpu.percent > 80 ? '#c62828' : '#667eea', borderRadius: '3px', transition: 'width 0.3s' }} />
              </div>
            </div>

            {/* 内存 */}
            <div className="stat-card">
              <div className="stat-icon" style={{ background: '#28a74520', color: '#28a745' }}>
                <Activity size={24} />
              </div>
              <div className="stat-value">{stats.memory.percent.toFixed(1)}%</div>
              <div className="stat-label">内存使用率</div>
              <div style={{ fontSize: '0.85rem', color: '#666', marginTop: '4px' }}>
                {formatBytes(stats.memory.used)} / {formatBytes(stats.memory.total)}
              </div>
              <div style={{ marginTop: '8px', height: '6px', background: '#e0e0e0', borderRadius: '3px', overflow: 'hidden' }}>
                <div style={{ width: `${stats.memory.percent}%`, height: '100%', background: stats.memory.percent > 80 ? '#c62828' : '#28a745', borderRadius: '3px', transition: 'width 0.3s' }} />
              </div>
            </div>

            {/* 磁盘 */}
            <div className="stat-card">
              <div className="stat-icon" style={{ background: '#ffc10720', color: '#ffc107' }}>
                <HardDrive size={24} />
              </div>
              <div className="stat-value">{stats.disk.percent}%</div>
              <div className="stat-label">磁盘使用率</div>
              <div style={{ fontSize: '0.85rem', color: '#666', marginTop: '4px' }}>
                {formatBytes(stats.disk.used)} / {formatBytes(stats.disk.total)}
              </div>
              <div style={{ marginTop: '8px', height: '6px', background: '#e0e0e0', borderRadius: '3px', overflow: 'hidden' }}>
                <div style={{ width: `${stats.disk.percent}%`, height: '100%', background: stats.disk.percent > 80 ? '#c62828' : '#ffc107', borderRadius: '3px', transition: 'width 0.3s' }} />
              </div>
            </div>

            {/* 网络 */}
            <div className="stat-card">
              <div className="stat-icon" style={{ background: '#17a2b820', color: '#17a2b8' }}>
                <Wifi size={24} />
              </div>
              <div className="stat-value">{(stats.network.bytes_recv / 1024 / 1024 / 1024).toFixed(2)} GB</div>
              <div className="stat-label">接收流量</div>
              <div style={{ fontSize: '0.85rem', color: '#666', marginTop: '4px' }}>
                发送: {(stats.network.bytes_sent / 1024 / 1024 / 1024).toFixed(2)} GB
              </div>
            </div>
          </div>

          {/* 详细内存信息 */}
          <div className="card" style={{ marginBottom: '24px' }}>
            <h3 style={{ marginBottom: '16px' }}>内存详情</h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: '16px' }}>
              <div style={{ background: '#f8f9fa', padding: '16px', borderRadius: '8px' }}>
                <div style={{ fontSize: '0.85rem', color: '#666', marginBottom: '4px' }}>总内存</div>
                <div style={{ fontSize: '1.2rem', fontWeight: 600 }}>{formatBytes(stats.memory.total)}</div>
              </div>
              <div style={{ background: '#f8f9fa', padding: '16px', borderRadius: '8px' }}>
                <div style={{ fontSize: '0.85rem', color: '#666', marginBottom: '4px' }}>已使用</div>
                <div style={{ fontSize: '1.2rem', fontWeight: 600, color: '#667eea' }}>{formatBytes(stats.memory.used)}</div>
              </div>
              <div style={{ background: '#f8f9fa', padding: '16px', borderRadius: '8px' }}>
                <div style={{ fontSize: '0.85rem', color: '#666', marginBottom: '4px' }}>可用</div>
                <div style={{ fontSize: '1.2rem', fontWeight: 600, color: '#28a745' }}>{formatBytes(stats.memory.available)}</div>
              </div>
              <div style={{ background: '#f8f9fa', padding: '16px', borderRadius: '8px' }}>
                <div style={{ fontSize: '0.85rem', color: '#666', marginBottom: '4px' }}>空闲</div>
                <div style={{ fontSize: '1.2rem', fontWeight: 600 }}>{formatBytes(stats.memory.free)}</div>
              </div>
            </div>
          </div>
        </>
      )}

      <style>{`
        @keyframes spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  )
}
