import { useState, useEffect } from 'react'
import { Target, Activity, Zap, TrendingUp, AlertCircle, CheckCircle } from 'lucide-react'

// 用户确认的目标指标配置
const GOAL_METRICS = {
  energyHomeostasis: {
    id: 'energy',
    name: '能量稳态管理',
    icon: Activity,
    color: '#10b981',
    metrics: [
      { name: '体重控制', target: 75, current: null, unit: 'kg', description: '控制到75公斤' },
      { name: '每周运动', target: 3, current: null, unit: '次', description: '每周运动3次' },
      { name: '睡眠质量', target: '标准', current: null, unit: '分', description: '达到标准分' }
    ]
  },
  t109Fusion: {
    id: 't109',
    name: 'T109 AI引擎融合',
    icon: Zap,
    color: '#3b82f6',
    metrics: [
      { name: '支持软件', target: 7, current: null, unit: '个', description: 'PSI4/PySCF/ORCA/Gaussian/CP2K/LAMMPS/GROMACS' },
      { name: '网站用户', target: 1000, current: null, unit: '人', description: '超过1000用户' },
      { name: '付费用户', target: 100, current: null, unit: '人', description: '超过100付费用户' },
      { name: 'AI优化', target: '完成', current: null, unit: '', description: 'AI优化基组和过渡态选择' }
    ]
  },
  pepiAgent: {
    id: 'pepi',
    name: 'Pepi自主代理',
    icon: Target,
    color: '#8b5cf6',
    metrics: [
      { name: '自动化率', target: 95, current: null, unit: '%', description: '95%自动化率' }
    ]
  }
}

interface MetricCardProps {
  goal: typeof GOAL_METRICS.energyHomeostasis
}

function MetricCard({ goal }: MetricCardProps) {
  const Icon = goal.icon
  
  const calculateProgress = (metric: any) => {
    if (metric.current === null) return 0
    if (typeof metric.target === 'string') {
      return metric.current === metric.target ? 100 : 0
    }
    return Math.min(100, Math.round((metric.current / metric.target) * 100))
  }

  const totalProgress = Math.round(
    goal.metrics.reduce((sum, m) => sum + calculateProgress(m), 0) / goal.metrics.length
  )

  return (
    <div style={{
      background: 'white',
      borderRadius: '12px',
      padding: '20px',
      marginBottom: '16px',
      boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
      borderLeft: `4px solid ${goal.color}`
    }}>
      {/* 标题栏 */}
      <div style={{ display: 'flex', alignItems: 'center', marginBottom: '16px' }}>
        <div style={{
          width: '40px',
          height: '40px',
          borderRadius: '10px',
          background: `${goal.color}20`,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          marginRight: '12px'
        }}>
          <Icon size={20} color={goal.color} />
        </div>
        <div style={{ flex: 1 }}>
          <h3 style={{ margin: 0, fontSize: '16px', fontWeight: 600, color: '#1f2937' }}>
            {goal.name}
          </h3>
          <div style={{ display: 'flex', alignItems: 'center', marginTop: '4px' }}>
            <div style={{
              width: '100px',
              height: '6px',
              background: '#e5e7eb',
              borderRadius: '3px',
              marginRight: '8px'
            }}>
              <div style={{
                width: `${totalProgress}%`,
                height: '100%',
                background: goal.color,
                borderRadius: '3px',
                transition: 'width 0.3s ease'
              }} />
            </div>
            <span style={{ fontSize: '14px', fontWeight: 600, color: goal.color }}>
              {totalProgress}%
            </span>
          </div>
        </div>
      </div>

      {/* 指标详情 */}
      <div style={{ display: 'grid', gap: '12px' }}>
        {goal.metrics.map((metric, idx) => {
          const progress = calculateProgress(metric)
          const isComplete = progress === 100
          
          return (
            <div key={idx} style={{
              display: 'flex',
              alignItems: 'center',
              padding: '12px',
              background: '#f9fafb',
              borderRadius: '8px',
              border: isComplete ? '1px solid #10b981' : '1px solid transparent'
            }}>
              <div style={{ flex: 1 }}>
                <div style={{ display: 'flex', alignItems: 'center', marginBottom: '4px' }}>
                  {isComplete ? (
                    <CheckCircle size={16} color="#10b981" style={{ marginRight: '8px' }} />
                  ) : (
                    <AlertCircle size={16} color="#f59e0b" style={{ marginRight: '8px' }} />
                  )}
                  <span style={{ fontSize: '14px', fontWeight: 500, color: '#374151' }}>
                    {metric.name}
                  </span>
                </div>
                <div style={{ fontSize: '12px', color: '#6b7280', marginLeft: '24px' }}>
                  {metric.description}
                </div>
              </div>
              <div style={{ textAlign: 'right' }}>
                <div style={{ fontSize: '18px', fontWeight: 700, color: isComplete ? '#10b981' : '#374151' }}>
                  {metric.current !== null ? `${metric.current}${metric.unit}` : `--${metric.unit}`}
                </div>
                <div style={{ fontSize: '12px', color: '#9ca3af' }}>
                  目标: {metric.target}{metric.unit}
                </div>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

export function GoalMetricsDashboard() {
  const [lastUpdated, setLastUpdated] = useState(new Date())

  useEffect(() => {
    const timer = setInterval(() => {
      setLastUpdated(new Date())
    }, 60000) // 每分钟更新
    return () => clearInterval(timer)
  }, [])

  const overallProgress = Math.round(
    Object.values(GOAL_METRICS).reduce((sum, goal) => {
      const goalProgress = goal.metrics.reduce((mSum, m) => {
        if (m.current === null) return mSum
        if (typeof m.target === 'string') return m.current === m.target ? mSum + 100 : mSum
        return mSum + Math.min(100, (m.current / m.target) * 100)
      }, 0) / goal.metrics.length
      return sum + goalProgress
    }, 0) / Object.keys(GOAL_METRICS).length
  )

  return (
    <div>
      {/* 总体进度 */}
      <div style={{
        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        borderRadius: '16px',
        padding: '24px',
        marginBottom: '24px',
        color: 'white'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <h2 style={{ margin: '0 0 8px 0', fontSize: '20px' }}>🎯 战略目标看板</h2>
            <p style={{ margin: 0, opacity: 0.9, fontSize: '14px' }}>
              3大核心目标实时追踪 | 最后更新: {lastUpdated.toLocaleTimeString()}
            </p>
          </div>
          <div style={{ textAlign: 'center' }}>
            <div style={{ fontSize: '48px', fontWeight: 700 }}>{overallProgress}%</div>
            <div style={{ fontSize: '14px', opacity: 0.9 }}>总体完成度</div>
          </div>
        </div>
        <div style={{
          marginTop: '16px',
          height: '8px',
          background: 'rgba(255,255,255,0.3)',
          borderRadius: '4px'
        }}>
          <div style={{
            width: `${overallProgress}%`,
            height: '100%',
            background: 'white',
            borderRadius: '4px',
            transition: 'width 0.5s ease'
          }} />
        </div>
      </div>

      {/* 目标卡片 */}
      <MetricCard goal={GOAL_METRICS.energyHomeostasis} />
      <MetricCard goal={GOAL_METRICS.t109Fusion} />
      <MetricCard goal={GOAL_METRICS.pepiAgent} />

      {/* 提示信息 */}
      <div style={{
        background: '#fef3c7',
        border: '1px solid #fbbf24',
        borderRadius: '8px',
        padding: '12px 16px',
        marginTop: '16px',
        display: 'flex',
        alignItems: 'center'
      }}>
        <TrendingUp size={20} color="#f59e0b" style={{ marginRight: '12px' }} />
        <span style={{ fontSize: '14px', color: '#92400e' }}>
          提示：当前指标数据需要从Gear System同步，点击指标可手动更新
        </span>
      </div>
    </div>
  )
}

export default GoalMetricsDashboard
