import { useState, useEffect } from 'react'
import './AdminDashboard.css'

interface DashboardStats {
  users: {
    total: number
    active: number
    inactive: number
  }
  tasks: {
    total: number
    pending: number
    completed: number
    completion_rate: number
  }
  projects: {
    total: number
  }
  task_trend: Record<string, number>
  recent_logins: Array<{
    username: string
    last_login: string
  }>
}

interface SystemHealth {
  status: 'healthy' | 'warning' | 'critical'
  issues: string[]
  cpu: { percent: number; status: string }
  memory: { percent: number; status: string }
  disk: { percent: number; status: string }
  database: { status: string }
  timestamp: string
}

export function AdminDashboard() {
  const [stats, setStats] = useState<DashboardStats | null>(null)
  const [health, setHealth] = useState<SystemHealth | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8086'
  const token = localStorage.getItem('kanban_token')

  useEffect(() => {
    fetchDashboardData()
    const interval = setInterval(fetchHealthData, 30000) // 每30秒刷新健康状态
    return () => clearInterval(interval)
  }, [])

  const fetchDashboardData = async () => {
    try {
      const response = await fetch(`${API_URL}/api/admin/dashboard`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()
      
      if (data.success) {
        setStats(data.data.stats)
        setHealth(data.data.health)
      } else {
        setError(data.error || '获取数据失败')
      }
    } catch (err) {
      setError('网络错误')
    } finally {
      setLoading(false)
    }
  }

  const fetchHealthData = async () => {
    try {
      const response = await fetch(`${API_URL}/api/admin/dashboard/health`, {
        headers: { 'Authorization': `Bearer ${token}` }
      })
      const data = await response.json()
      
      if (data.success) {
        setHealth(data.data)
      }
    } catch (err) {
      console.error('获取健康状态失败:', err)
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'healthy': return '#52c41a'
      case 'warning': return '#faad14'
      case 'critical': return '#f5222d'
      default: return '#d9d9d9'
    }
  }

  const getStatusText = (status: string) => {
    switch (status) {
      case 'healthy': return '健康'
      case 'warning': return '警告'
      case 'critical': return '严重'
      default: return '未知'
    }
  }

  if (loading) return <div className="admin-loading">加载中...</div>
  if (error) return <div className="admin-error">{error}</div>
  if (!stats) return <div className="admin-error">暂无数据</div>

  return (
    <div className="admin-dashboard">
      <h1>管理仪表盘</h1>
      
      {/* 系统健康状态 */}
      <div className="health-card">
        <div className="health-header">
          <h2>系统健康状态</h2>
          <span 
            className="health-badge"
            style={{ backgroundColor: getStatusColor(health?.status || 'unknown') }}
          >
            {getStatusText(health?.status || 'unknown')}
          </span>
        </div>
        
        {health?.issues && health.issues.length > 0 && (
          <div className="health-issues">
            {health.issues.map((issue, index) => (
              <div key={index} className="issue-item">⚠️ {issue}</div>
            ))}
          </div>
        )}
        
        <div className="health-metrics">
          <div className="metric-item">
            <span className="metric-label">CPU</span>
            <div className="metric-bar">
              <div 
                className="metric-fill"
                style={{ 
                  width: `${health?.cpu.percent || 0}%`,
                  backgroundColor: getStatusColor(health?.cpu.status || 'healthy')
                }}
              />
            </div>
            <span className="metric-value">{health?.cpu.percent.toFixed(1)}%</span>
          </div>
          
          <div className="metric-item">
            <span className="metric-label">内存</span>
            <div className="metric-bar">
              <div 
                className="metric-fill"
                style={{ 
                  width: `${health?.memory.percent || 0}%`,
                  backgroundColor: getStatusColor(health?.memory.status || 'healthy')
                }}
              />
            </div>
            <span className="metric-value">{health?.memory.percent.toFixed(1)}%</span>
          </div>
          
          <div className="metric-item">
            <span className="metric-label">磁盘</span>
            <div className="metric-bar">
              <div 
                className="metric-fill"
                style={{ 
                  width: `${health?.disk.percent || 0}%`,
                  backgroundColor: getStatusColor(health?.disk.status || 'healthy')
                }}
              />
            </div>
            <span className="metric-value">{health?.disk.percent.toFixed(1)}%</span>
          </div>
          
          <div className="metric-item">
            <span className="metric-label">数据库</span>
            <span 
              className="metric-status"
              style={{ color: getStatusColor(health?.database.status || 'healthy') }}
            >
              {health?.database.status === 'healthy' ? '正常' : '异常'}
            </span>
          </div>
        </div>
      </div>

      {/* 统计卡片 */}
      <div className="stats-grid">
        <div className="stat-card users">
          <div className="stat-icon">👥</div>
          <div className="stat-content">
            <h3>用户总数</h3>
            <p className="stat-value">{stats.users.total}</p>
            <p className="stat-detail">
              活跃: {stats.users.active} | 禁用: {stats.users.inactive}
            </p>
          </div>
        </div>
        
        <div className="stat-card tasks">
          <div className="stat-icon">📋</div>
          <div className="stat-content">
            <h3>任务总数</h3>
            <p className="stat-value">{stats.tasks.total}</p>
            <p className="stat-detail">
              待处理: {stats.tasks.pending} | 完成率: {stats.tasks.completion_rate}%
            </p>
          </div>
        </div>
        
        <div className="stat-card projects">
          <div className="stat-icon">📁</div>
          <div className="stat-content">
            <h3>项目总数</h3>
            <p className="stat-value">{stats.projects.total}</p>
          </div>
        </div>
        
        <div className="stat-card completion">
          <div className="stat-icon">✅</div>
          <div className="stat-content">
            <h3>已完成任务</h3>
            <p className="stat-value">{stats.tasks.completed}</p>
          </div>
        </div>
      </div>

      {/* 最近登录 */}
      <div className="recent-logins">
        <h2>最近登录</h2>
        <table className="admin-table">
          <thead>
            <tr>
              <th>用户名</th>
              <th>最后登录时间</th>
            </tr>
          </thead>
          <tbody>
            {stats.recent_logins.map((login, index) => (
              <tr key={index}>
                <td>{login.username}</td>
                <td>{new Date(login.last_login).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}
