// ==================== Helper Components ====================
const Badge = ({ children, type }: { children: React.ReactNode; type?: 'success' | 'warning' | 'error' | 'info' | 'announcement' | 'news' | 'activity' | 'primary' }) => {
  const colors: Record<string, { bg: string; color: string }> = {
    success: { bg: '#d4edda', color: '#155724' },
    warning: { bg: '#fff3cd', color: '#856404' },
    error: { bg: '#f8d7da', color: '#721c24' },
    info: { bg: '#cce5ff', color: '#004085' },
    primary: { bg: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', color: 'white' },
    announcement: { bg: '#fff3cd', color: '#856404' },
    news: { bg: '#cce5ff', color: '#004085' },
    activity: { bg: '#d4edda', color: '#155724' }
  }
  const style = type ? colors[type] || colors.info : colors.info
  return (
    <span style={{
      padding: '4px 10px',
      borderRadius: '12px',
      fontSize: '0.75rem',
      fontWeight: 600,
      background: style.bg,
      color: style.color
    }}>
      {children}
    </span>
  )
}

const Button = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  onClick, 
  disabled = false
}: { 
  children: React.ReactNode
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost'
  size?: 'sm' | 'md' | 'lg'
  onClick?: () => void
  disabled?: boolean
}) => {
  const variants = {
    primary: { bg: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', color: 'white', border: 'none' },
    secondary: { bg: '#e9ecef', color: '#495057', border: 'none' },
    danger: { bg: '#dc3545', color: 'white', border: 'none' },
    ghost: { bg: 'transparent', color: '#667eea', border: '1px solid #667eea' }
  }
  const sizes = {
    sm: { padding: '6px 12px', fontSize: '12px' },
    md: { padding: '10px 20px', fontSize: '14px' },
    lg: { padding: '14px 28px', fontSize: '16px' }
  }
  const v = variants[variant]
  const s = sizes[size]
  
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      style={{
        background: v.bg,
        color: v.color,
        border: v.border,
        padding: s.padding,
        fontSize: s.fontSize,
        borderRadius: '8px',
        cursor: disabled ? 'not-allowed' : 'pointer',
        fontWeight: 500,
        transition: 'all 0.2s',
        opacity: disabled ? 0.6 : 1,
        display: 'inline-flex',
        alignItems: 'center',
        gap: '8px'
      }}
    >
      {children}
    </button>
  )
}

const Input = ({ 
  label, 
  value, 
  onChange, 
  type = 'text', 
  placeholder = '', 
  required = false,
  error = ''
}: { 
  label: string
  value: string
  onChange: (val: string) => void
  type?: string
  placeholder?: string
  required?: boolean
  error?: string
}) => (
  <div style={{ marginBottom: '16px' }}>
    <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500, color: '#555' }}>
      {label}
      {required && <span style={{ color: '#dc3545', marginLeft: '4px' }}>*</span>}
    </label>
    <input
      type={type}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      style={{
        width: '100%',
        padding: '10px 12px',
        border: `1px solid ${error ? '#dc3545' : '#ddd'}`,
        borderRadius: '6px',
        fontSize: '14px',
        outline: 'none',
        transition: 'border-color 0.2s'
      }}
    />
    {error && <span style={{ color: '#dc3545', fontSize: '12px', marginTop: '4px', display: 'block' }}>{error}</span>}
  </div>
)

const TextArea = ({ 
  label, 
  value, 
  onChange, 
  placeholder = '', 
  required = false,
  rows = 4
}: { 
  label: string
  value: string
  onChange: (val: string) => void
  placeholder?: string
  required?: boolean
  rows?: number
}) => (
  <div style={{ marginBottom: '16px' }}>
    <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500, color: '#555' }}>
      {label}
      {required && <span style={{ color: '#dc3545', marginLeft: '4px' }}>*</span>}
    </label>
    <textarea
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      rows={rows}
      style={{
        width: '100%',
        padding: '10px 12px',
        border: '1px solid #ddd',
        borderRadius: '6px',
        fontSize: '14px',
        resize: 'vertical',
        outline: 'none',
        fontFamily: 'inherit',
        transition: 'border-color 0.2s'
      }}
    />
  </div>
)

const Select = ({ 
  label, 
  value, 
  onChange, 
  options,
  required = false
}: { 
  label: string
  value: string
  onChange: (val: string) => void
  options: { value: string; label: string }[]
  required?: boolean
}) => (
  <div style={{ marginBottom: '16px' }}>
    <label style={{ display: 'block', marginBottom: '6px', fontWeight: 500, color: '#555' }}>
      {label}
      {required && <span style={{ color: '#dc3545', marginLeft: '4px' }}>*</span>}
    </label>
    <select
      value={value}
      onChange={(e) => onChange(e.target.value)}
      style={{
        width: '100%',
        padding: '10px 12px',
        border: '1px solid #ddd',
        borderRadius: '6px',
        fontSize: '14px',
        outline: 'none',
        backgroundColor: 'white',
        cursor: 'pointer'
      }}
    >
      {options.map(opt => (
        <option key={opt.value} value={opt.value}>{opt.label}</option>
      ))}
    </select>
  </div>
)

const Modal = ({ 
  isOpen, 
  onClose, 
  title, 
  children,
  size = 'md'
}: { 
  isOpen: boolean
  onClose: () => void
  title: string
  children: React.ReactNode
  size?: 'sm' | 'md' | 'lg'
}) => {
  if (!isOpen) return null
  const widths = { sm: '400px', md: '500px', lg: '700px' }
  
  return (
    <div 
      style={{
        position: 'fixed',
        top: 0, left: 0, right: 0, bottom: 0,
        background: 'rgba(0,0,0,0.5)',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        zIndex: 2000
      }}
      onClick={onClose}
    >
      <div 
        style={{
          background: 'white',
          padding: '24px',
          borderRadius: '12px',
          width: '90%',
          maxWidth: widths[size],
          maxHeight: '90vh',
          overflow: 'auto',
          boxShadow: '0 20px 60px rgba(0,0,0,0.3)'
        }}
        onClick={(e) => e.stopPropagation()}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h3 style={{ margin: 0, color: '#333' }}>{title}</h3>
          <button onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer', padding: '4px' }}>
            <X size={24} color="#666" />
          </button>
        </div>
        {children}
      </div>
    </div>
  )
}

const InfoItem = ({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) => (
  <div style={{ display: 'flex', alignItems: 'flex-start', gap: '12px', marginBottom: '16px' }}>
    <div style={{ color: '#667eea', marginTop: '2px' }}>{icon}</div>
    <div>
      <label style={{ color: '#666', fontSize: '0.85rem', display: 'block', marginBottom: '2px' }}>{label}</label>
      <span style={{ color: '#333', fontWeight: 500 }}>{value || '-'}</span>
    </div>
  </div>
)

const Avatar = ({ name, src, size = 48 }: { name: string; src?: string; size?: number }) => {
  const initials = name.slice(0, 2).toUpperCase()
  const colors = ['#667eea', '#764ba2', '#11998e', '#fc4a1a', '#4facfe']
  const color = colors[name.charCodeAt(0) % colors.length]
  
  return (
    <div style={{
      width: size,
      height: size,
      borderRadius: '50%',
      background: src ? `url(${src}) center/cover` : color,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      color: 'white',
      fontWeight: 600,
      fontSize: size / 2.5,
      flexShrink: 0
    }}>
      {!src && initials}
    </div>
  )
}

// ==================== Main Component ====================
export function CompanyInfo() {
  const navigate = useNavigate()
  const [activeTab, setActiveTab] = useState<TabType>('basic')
  const [company, setCompany] = useState<Company | null>(null)
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([])
  const [news, setNews] = useState<CompanyNews[]>([])
  const [loading, setLoading] = useState(true)
  const [isAdmin] = useState(true)
  const [showToast, setShowToast] = useState<{ show: boolean; message: string; type: 'success' | 'error' }>(
    { show: false, message: '', type: 'success' }
  )

  // Basic Info States
  const [isEditingBasic, setIsEditingBasic] = useState(false)
  const [editForm, setEditForm] = useState<Partial<Company>>({})
  const [formErrors, setFormErrors] = useState<Record<string, string>>({})

  // Team Member States
  const [teamModalOpen, setTeamModalOpen] = useState(false)
  const [editingMember, setEditingMember] = useState<TeamMember | null>(null)
  const [memberForm, setMemberForm] = useState<Partial<TeamMember>>({})

  // News States
  const [newsModalOpen, setNewsModalOpen] = useState(false)
  const [editingNews, setEditingNews] = useState<CompanyNews | null>(null)
  const [newsForm, setNewsForm] = useState<Partial<CompanyNews>>({})

  // Logo States
  const [logoPreview, setLogoPreview] = useState<string | null>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [logoScale, setLogoScale] = useState(100)
  const fileInputRef = useRef<HTMLInputElement>(null)

  // Load Data
  useEffect(() => {
    const loadData = async () => {
      setTimeout(() => {
        setCompany(mockCompany)
        setTeamMembers(mockTeamMembers)
        setNews(mockNews)
        setLoading(false)
      }, 500)
    }
    loadData()
  }, [])

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setShowToast({ show: true, message, type })
    setTimeout(() => setShowToast({ show: false, message: '', type }), 3000)
  }

  // Tab Configuration
  const tabs = [
    { id: 'basic' as TabType, label: '基本信息', icon: Building2 },
    { id: 'logo' as TabType, label: 'Logo设置', icon: Camera },
    { id: 'team' as TabType, label: '团队成员', icon: Users },
    { id: 'news' as TabType, label: '公司动态', icon: FileText }
  ]

  // Basic Info Handlers
  const handleEditStart = () => {
    setEditForm(company || {})
    setIsEditingBasic(true)
    setFormErrors({})
  }

  const validateBasicForm = (): boolean => {
    const errors: Record<string, string> = {}
    if (!editForm.name?.trim()) errors.name = '公司名称不能为空'
    if (!editForm.shortName?.trim()) errors.shortName = '公司简称不能为空'
    if (!editForm.industry?.trim()) errors.industry = '所属行业不能为空'
    if (!editForm.email?.trim()) {
      errors.email = '邮箱不能为空'
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(editForm.email)) {
      errors.email = '邮箱格式不正确'
    }
    if (!editForm.phone?.trim()) errors.phone = '联系电话不能为空'
    if (editForm.website && !/^https?:\/\/.+/.test(editForm.website)) {
      errors.website = '网站格式不正确，请以http://或https://开头'
    }
    setFormErrors(errors)
    return Object.keys(errors).length === 0
  }

  const handleSaveBasic = () => {
    if (!validateBasicForm()) return
    setCompany(prev => prev ? { 
      ...prev, 
      ...editForm, 
      lastUpdated: new Date().toISOString().split('T')[0] 
    } : null)
    setIsEditingBasic(false)
    showNotification('公司信息保存成功')
  }

  // Logo Handlers
  const handleFileSelect = (file: File) => {
    if (!file.type.startsWith('image/')) {
      showNotification('请上传图片文件', 'error')
      return
    }
    if (file.size > 5 * 1024 * 1024) {
      showNotification('图片大小不能超过5MB', 'error')
      return
    }
    const reader = new FileReader()
    reader.onload = (e) => {
      setLogoPreview(e.target?.result as string)
      showNotification('Logo预览已生成')
    }
    reader.readAsDataURL(file)
  }

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(false)
    const file = e.dataTransfer.files[0]
    if (file) handleFileSelect(file)
  }, [])

  const handleSaveLogo = () => {
    if (logoPreview && company) {
      setCompany({ ...company, logo: logoPreview })
      setLogoPreview(null)
      setLogoScale(100)
      showNotification('Logo保存成功')
    }
  }

  // Team Member Handlers
  const handleAddMember = () => {
    setEditingMember(null)
    setMemberForm({ 
      status: 'active', 
      joinDate: new Date().toISOString().split('T')[0] 
    })
    setTeamModalOpen(true)
  }

  const handleEditMember = (member: TeamMember) => {
    setEditingMember(member)
    setMemberForm(member)
    setTeamModalOpen(true)
  }

  const handleDeleteMember = (id: string) => {
    if (confirm('确定要删除该成员吗？此操作不可撤销。')) {
      setTeamMembers(prev => prev.filter(m => m.id !== id))
      showNotification('成员删除成功')
    }
  }

  const validateMemberForm = (): boolean => {
    if (!memberForm.name?.trim()) { 
      showNotification('姓名不能为空', 'error') 
      return false 
    }
    if (!memberForm.position?.trim()) { 
      showNotification('职位不能为空', 'error') 
      return false 
    }
    if (!memberForm.department?.trim()) { 
      showNotification('部门不能为空', 'error') 
      return false 
    }
    if (memberForm.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(memberForm.email)) {
      showNotification('邮箱格式不正确', 'error')
      return false
    }
    return true
  }

  const handleSaveMember = () => {
    if (!validateMemberForm()) return
    if (editingMember) {
      setTeamMembers(prev => prev.map(m => 
        m.id === editingMember.id ? { ...m, ...memberForm } as TeamMember : m
      ))
      showNotification('成员信息更新成功')
    } else {
      const newMember: TeamMember = {
        id: Date.now().toString(),
        name: memberForm.name || '',
        position: memberForm.position || '',
        department: memberForm.department || '',
        email: memberForm.email || '',
        phone: memberForm.phone || '',
        avatar: memberForm.avatar || '',
        joinDate: memberForm.joinDate || new Date().toISOString().split('T')[0],
        status: memberForm.status as 'active' | 'inactive' || 'active',
        bio: memberForm.bio
      }
      setTeamMembers(prev => [...prev, newMember])
      showNotification('新成员添加成功')
    }
    setTeamModalOpen(false)
  }

  // News Handlers
  const handleAddNews = () => {
    setEditingNews(null)
    setNewsForm({ 
      category: 'news', 
      publishDate: new Date().toISOString().split('T')[0], 
      views: 0, 
      isTop: false 
    })
    setNewsModalOpen(true)
  }

  const handleEditNews = (item: CompanyNews) => {
    setEditingNews(item)
    setNewsForm(item)
    setNewsModalOpen(true)
  }

  const handleDeleteNews = (id: string) => {
    if (confirm('确定要删除这条动态吗？此操作不可撤销。')) {
      setNews(prev => prev.filter(n => n.id !== id))
      showNotification('动态删除成功')
    }
  }

  const handleToggleTop = (item: CompanyNews) => {
    setNews(prev => prev.map(n => 
      n.id === item.id ? { ...n, isTop: !n.isTop } : n
    ))
    showNotification(item.isTop ? '已取消置顶' : '已置顶')
  }

  const validateNewsForm = (): boolean => {
    if (!newsForm.title?.trim()) { 
      showNotification('标题不能为空', 'error') 
      return false 
    }
    if (!newsForm.content?.trim()) { 
      showNotification('内容不能为空', 'error') 
      return false 
    }
    if (newsForm.title.length > 100) {
      showNotification('标题不能超过100个字符', 'error')
      return false
    }
    return true
  }

  const handleSaveNews = () => {
    if (!validateNewsForm()) return
    if (editingNews) {
      setNews(prev => prev.map(n => 
        n.id === editingNews.id ? { ...n, ...newsForm } as CompanyNews : n
      ))
      showNotification('动态更新成功')
    } else {
      const newNews: CompanyNews = {
        id: Date.now().toString(),
        title: newsForm.title || '',
        content: newsForm.content || '',
        category: newsForm.category as 'announcement' | 'news' | 'activity' || 'news',
        author: '管理员',
        publishDate: newsForm.publishDate || new Date().toISOString().split('T')[0],
        views: 0,
        isTop: newsForm.isTop || false
      }
      setNews(prev => [newNews, ...prev])
      showNotification('动态发布成功')
    }
    setNewsModalOpen(false)
  }

  // Sort news: top first, then by date
  const sortedNews = [...news].sort((a, b) => {
    if (a.isTop && !b.isTop) return -1
    if (!a.isTop && b.isTop) return 1
    return new Date(b.publishDate).getTime() - new Date(a.publishDate).getTime()
  })

  const getCategoryLabel = (category: string) => {
    const map: Record<string, string> = { 
      announcement: '公告', 
      news: '新闻', 
      activity: '活动' 
    }
    return map[category] || category
  }

  if (loading) {
    return (
      <div className="page-container">
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '400px' }}>
          <div style={{ textAlign: 'center' }}>
            <div style={{ 
              width: '48px', 
              height: '48px', 
              border: '3px solid #f3f3f3', 
              borderTop: '3px solid #667eea', 
              borderRadius: '50%', 
              animation: 'spin 1s linear infinite',
              margin: '0 auto 16px'
            }} />
            <p style={{ color: '#666' }}>加载中...</p>
          </div>
        </div>
      </div>
    )
  }

  if (!company) {
    return (
      <div className="page-container">
        <div className="card" style={{ textAlign: 'center', padding: '60px' }}>
          <AlertCircle size={64} color="#dc3545" style={{ marginBottom: '16px' }} />
          <h3 style={{ color: '#333', marginBottom: '8px' }}>加载失败</h3>
          <p style={{ color: '#666' }}>无法获取公司信息，请稍后重试</p>
        </div>
      </div>
    )
  }

  return (
    <div className="page-container">
      {/* Toast Notification */}
      {showToast.show && (
        <div style={{ 
          position: 'fixed', 
          top: '80px', 
          right: '24px', 
          background: showToast.type === 'success' ? '#28a745' : '#dc3545', 
          color: 'white', 
          padding: '12px 20px', 
          borderRadius: '8px', 
          zIndex: 3000, 
          display: 'flex', 
          alignItems: 'center', 
          gap: '8px',
          boxShadow: '0 4px 12px rgba(0,0,0,0.15)'
        }}>
          {showToast.type === 'success' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
          {showToast.message}
        </div>
      )}

      {/* Page Header */}
      <div className="page-header">
        <div>
          <h2 className="page-title">🏢 公司信息管理</h2>
          <p style={{ color: '#666', marginTop: '8px' }}>管理公司档案、Logo、团队成员和企业动态</p>
        </div>
      </div>

      {/* Tabs */}
      <div className="card" style={{ padding: '12px', marginBottom: '24px' }}>
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          {tabs.map(tab => {
            const Icon = tab.icon
            const isActive = activeTab === tab.id
            return (
              <button 
                key={tab.id} 
                onClick={() => setActiveTab(tab.id)} 
                style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  gap: '8px', 
                  padding: '10px 20px', 
                  borderRadius: '8px', 
                  border: 'none', 
                  cursor: 'pointer', 
                  fontSize: '14px', 
                  fontWeight: 500, 
                  background: isActive ? 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' : 'transparent', 
                  color: isActive ? 'white' : '#666'
                }}
              >
                <Icon size={18} />{tab.label}
              </button>
            )
          })}
        </div>
      </div>

      {/* Basic Info Tab */}
      {activeTab === 'basic' && (
        <div className="card">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
            <h3 style={{ margin: 0 }}>基本信息</h3>
            {isAdmin && !isEditingBasic && (
              <Button variant="primary" size="sm" onClick={handleEditStart}>
                <Edit2 size={16} />编辑信息
              </Button>
            )}
            {isEditingBasic && (
              <div style={{ display: 'flex', gap: '8px' }}>
                <Button variant="secondary" size="sm" onClick={() => setIsEditingBasic(false)}>
                  <X size={16} />取消
                </Button>
                <Button variant="primary" size="sm" onClick={handleSaveBasic}>
                  <Save size={16} />保存
                </Button>
              </div>
            )}
          </div>
          
          {isEditingBasic ? (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '16px' }}>
              <Input label="公司名称" value={editForm.name || ''} onChange={v => setEditForm({ ...editForm, name: v })} required error={formErrors.name} />
              <Input label="公司简称" value={editForm.shortName || ''} onChange={v => setEditForm({ ...editForm, shortName: v })} required error={formErrors.shortName} />
              <Input label="所属行业" value={editForm.industry || ''} onChange={v => setEditForm({ ...editForm, industry: v })} required error={formErrors.industry} />
              <Input label="细分行业" value={editForm.subIndustry || ''} onChange={v => setEditForm({ ...editForm, subIndustry: v })} />
              <Input label="法定代表人" value={editForm.legalRepresentative || ''} onChange={v => setEditForm({ ...editForm, legalRepresentative: v })} />
              <Input label="成立日期" type="date" value={editForm.createDate || ''} onChange={v => setEditForm({ ...editForm, createDate: v })} />
              <Input label="注册资本" value={editForm.registeredCapital || ''} onChange={v => setEditForm({ ...editForm, registeredCapital: v })} />
              <Input label="统一社会信用代码" value={editForm.businessLicense || ''} onChange={v => setEditForm({ ...editForm, businessLicense: v })} />
              <div style={{ gridColumn: '1 / -1' }}>
                <TextArea label="公司简介" value={editForm.description || ''} onChange={v => setEditForm({ ...editForm, description: v })} rows={5} />
              </div>
              <Input label="公司地址" value={editForm.address || ''} onChange={v => setEditForm({ ...editForm, address: v })} />
              <Input label="联系电话" value={editForm.phone || ''} onChange={v => setEditForm({ ...editForm, phone: v })} required error={formErrors.phone} />
              <Input label="电子邮箱" type="email" value={editForm.email || ''} onChange={v => setEditForm({ ...editForm, email: v })} required error={formErrors.email} />
              <Input label="官方网站" value={editForm.website || ''} onChange={v => setEditForm({ ...editForm, website: v })} error={formErrors.website} />
            </div>
          ) : (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '24px' }}>
              <div>
                <InfoItem icon={<Building2 size={18} />} label="公司名称" value={company.name} />
                <InfoItem icon={<Building2 size={18} />} label="公司简称" value={company.shortName} />
                <InfoItem icon={<Globe size={18} />} label="所属行业" value={`${company.industry} / ${company.subIndustry}`} />
                <InfoItem icon={<Users size={18} />} label="法定代表人" value={company.legalRepresentative} />
                <InfoItem icon={<Calendar size={18} />} label="成立日期" value={company.createDate} />
                <InfoItem icon={<FileText size={18} />} label="注册资本" value={company.registeredCapital} />
                <InfoItem icon={<FileText size={18} />} label="统一社会信用代码" value={company.businessLicense} />
              </div>
              <div>
                <InfoItem icon={<MapPin size={18} />} label="公司地址" value={company.address} />
                <InfoItem icon={<Phone size={18} />} label="联系电话" value={company.phone} />
                <InfoItem icon={<Mail size={18} />} label="电子邮箱" value={company.email} />
                <InfoItem icon={<Globe size={18} />} label="官方网站" value={company.website} />
                <div style={{ marginTop: '16px' }}>
                  <label style={{ color: '#666', fontSize: '0.9rem', marginBottom: '8px', display: 'block' }}>公司简介</label>
                  <p style={{ color: '#333', lineHeight: 1.8, background: '#f8f9fa', padding: '16px', borderRadius: '8px' }}>
                    {company.description}
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Logo Tab */}
      {activeTab === 'logo' && (
        <div className="card">
          <h3 style={{ marginBottom: '24px' }}>Logo设置</h3>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '32px' }}>
            <div>
              <label style={{ display: 'block', marginBottom: '12px', fontWeight: 500 }}>当前Logo</label>
              <div style={{ 
                width: '200px', 
                height: '200px', 
                borderRadius: '12px', 
                background: company.logo ? `url(${company.logo}) center/contain no-repeat` : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'center', 
                border: '2px dashed #ddd', 
                marginBottom: '16px' 
              }}>
                {!company.logo && <Building2 size={64} color="white" />}
              </div>
              <p style={{ color: '#666', fontSize: '0.85rem' }}>推荐尺寸: 512 x 512 像素，支持 JPG、PNG 格式</p>
            </div>
            <div>
              <label style={{ display: 'block', marginBottom: '12px', fontWeight: 500 }}>上传新Logo</label>
              <div 
                onDrop={handleDrop} 
                onDragOver={(e) => { e.preventDefault(); setIsDragging(true) }} 
                onDragLeave={() => setIsDragging(false)} 
                onClick={() => fileInputRef.current?.click()} 
                style={{ 
                  border: `2px dashed ${isDragging ? '#667eea' : '#ddd'}`, 
                  borderRadius: '12px', 
                  padding: '48px 32px', 
                  textAlign: 'center', 
                  background: isDragging ? '#f0f4ff' : '#fafafa', 
                  cursor: 'pointer'
                }}
              >
                <Upload size={48} color="#667eea" style={{ marginBottom: '16px' }} />
                <p style={{ color: '#333', fontWeight: 500, marginBottom: '8px' }}>点击或拖拽上传Logo</p>
                <p style={{ color: '#999', fontSize: '0.85rem' }}>支持 JPG、PNG，最大 5MB</p>
                <input 
                  ref={fileInputRef} 
                  type="file" 
                  accept="image/*" 
                  style={{ display: 'none' }} 
                  onChange={(e) => e.target.files?.[0] && handleFileSelect(e.target.files[0])} 
                />
              </div>
              {logoPreview && (
                <div style={{ marginTop: '24px' }}>
                  <label style={{ display: 'block', marginBottom: '12px', fontWeight: 500 }}>预览</label>
                  <div style={{ 
                    width: '150px', 
                    height: '150px', 
                    borderRadius: '12px', 
                    background: `url(${logoPreview}) center/contain no-repeat`, 
                    border: '2px solid #667eea', 
                    marginBottom: '16px' 
                  }} />
                  <div style={{ display: 'flex', gap: '8px' }}>
                    <Button variant="primary" size="sm" onClick={handleSaveLogo}>
                      <Save size={16} />保存Logo
                    </Button>
                    <Button variant="secondary" size="sm" onClick={() => setLogoPreview(null)}>
                      <X size={16} />取消
                    </Button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Team Tab */}
      {activeTab === 'team' && (
        <div>
          <div className="card" style={{ marginBottom: '24px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <h3 style={{ margin: 0 }}>团队成员</h3>
                <p style={{ color: '#666', marginTop: '4px', fontSize: '0.9rem' }}>共 {teamMembers.length} 位成员</p>
              </div>
              {isAdmin && (
                <Button variant="primary" onClick={handleAddMember}>
                  <Plus size={18} />添加成员
                </Button>
              )}
            </div>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '16px' }}>
            {teamMembers.map(member => (
              <div key={member.id} className="card" style={{ position: 'relative' }}>
                {isAdmin && (
                  <div style={{ position: 'absolute', top: '16px', right: '16px', display: 'flex', gap: '8px' }}>
                    <button 
                      onClick={() => handleEditMember(member)} 
                      style={{ 
                        background: '#f0f4ff', 
                        border: 'none', 
                        width: '32px', 
                        height: '32px', 
                        borderRadius: '6px', 
                        cursor: 'pointer', 
                        display: 'flex', 
                        alignItems: 'center', 
                        justifyContent: 'center' 
                      }}
                    >
                      <Edit2 size={16} color="#667eea" />
                    </button>
                    <button 
                      onClick={() => handleDeleteMember(member.id)} 
                      style={{ 
                        background: '#f8d7da', 
                        border: 'none', 
                        width: '32px', 
                        height: '32px', 
                        borderRadius: '6px', 
                        cursor: 'pointer', 
                        display: 'flex', 
                        alignItems: 'center', 
                        justifyContent: 'center' 
                      }}
                    >
                      <Trash2 size={16} color="#dc3545" />
                    </button>
                  </div>
                )}
                <div style={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
                  <Avatar name={member.name} src={member.avatar} size={64} />
                  <div style={{ flex: 1 }}>
                    <h4 style={{ margin: '0 0 4px 0' }}>{member.name}</h4>
                    <p style={{ margin: '0 0 8px 0', color: '#667eea', fontWeight: 500 }}>{member.position}</p>
                    <Badge type={member.status === 'active' ? 'success' : 'error'}>
                      {member.status === 'active' ? '在职' : '离职'}
                    </Badge>
                  </div>
                </div>
                <div style={{ marginTop: '16px', paddingTop: '16px', borderTop: '1px solid #eee' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px', color: '#666', fontSize: '0.9rem' }}>
                    <Building2 size={16} />{member.department}
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px', color: '#666', fontSize: '0.9rem' }}>
                    <Mail size={16} />{member.email || '未设置'}
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px', color: '#666', fontSize: '0.9rem' }}>
                    <Phone size={16} />{member.phone || '未设置'}
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#666', fontSize: '0.9rem' }}>
                    <Calendar size={16} />入职时间: {member.joinDate}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* News Tab */}
      {activeTab === 'news' && (
        <div>
          <div className="card" style={{ marginBottom: '24px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <h3 style={{ margin: 0 }}>公司动态</h3>
                <p style={{ color: '#666', marginTop: '4px', fontSize: '0.9rem' }}>共 {news.length} 条动态</p>
              </div>
              {isAdmin && (
                <Button variant="primary" onClick={handleAddNews}>
                  <Plus size={18} />发布动态
                </Button>
              )}
            </div>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {sortedNews.map(item => (
              <div key={item.id} className="card" style={{ position: 'relative' }}>
                {item.isTop && (
                  <span style={{ 
                    position: 'absolute', 
                    top: 0, 
                    left: 0, 
                    background: '#dc3545', 
                    color: 'white', 
                    padding: '4px 12px', 
                    borderRadius: '12px 0 12px 0', 
                    fontSize: '0.75rem', 
                    fontWeight: 600 
                  }}>
                    置顶
                  </span>
                )}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '12px' }}>
                  <div>
                    <h4 style={{ margin: '0 0 8px 0' }}>{item.title}</h4>
                    <div style={{ display: 'flex', gap: '12px', alignItems: 'center' }}>
                      <Badge type={item.category}>{getCategoryLabel(item.category)}</Badge>
                      <span style={{ color: '#999', fontSize: '0.85rem' }}>{item.author}</span>
                      <span style={{ color: '#999', fontSize: '0.85rem' }}>{item.publishDate}</span>
                      <span style={{ color: '#999', fontSize: '0.85rem', display: 'flex', alignItems: 'center', gap: '4px' }}>
                        <Eye size={14} />{item.views}
                      </span>
                    </div>
                  </div>
                  {isAdmin && (
                    <div style={{ display: 'flex', gap: '8px' }}>
                      <button 
                        onClick={() => handleToggleTop(item)}
                        style={{ 
                          background: item.isTop ? '#fff3cd' : '#f0f4ff', 
                          border: 'none', 
                          width: '32px', 
                          height: '32px', 
                          borderRadius: '6px', 
                          cursor: 'pointer', 
                          display: 'flex', 
                          alignItems: 'center', 
                          justifyContent: 'center' 
                        }}
                        title={item.isTop ? '取消置顶' : '置顶'}
                      >
                        <Edit2 size={16} color={item.isTop ? '#856404' : '#667eea'} />
                      </button>
                      <button 
                        onClick={() => handleEditNews(item)} 
                        style={{ 
                          background: '#f0f4ff', 
                          border: 'none', 
                          width: '32px', 
                          height: '32px', 
                          borderRadius: '6px', 
                          cursor: 'pointer', 
                          display: 'flex', 
                          alignItems: 'center', 
                          justifyContent: 'center' 
                        }}
                      >
                        <Edit2 size={16} color="#667eea" />
                      </button>
                      <button 
                        onClick={() => handleDeleteNews(item.id)} 
                        style={{ 
                          background: '#f8d7da', 
                          border: 'none', 
                          width: '32px', 
                          height: '32px', 
                          borderRadius: '6px', 
                          cursor: 'pointer', 
                          display: 'flex', 
                          alignItems: 'center', 
                          justifyContent: 'center' 
                        }}
                      >
                        <Trash2 size={16} color="#dc3545" />
                      </button>
                    </div>
                  )}
                </div>
                <p style={{ color: '#666', lineHeight: 1.8, margin: 0 }}>{item.content}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Team Member Modal */}
      <Modal isOpen={teamModalOpen} onClose={() => setTeamModalOpen(false)} title={editingMember ? '编辑成员' : '添加成员'}>
        <Input label="姓名" value={memberForm.name || ''} onChange={v => setMemberForm({ ...memberForm, name: v })} required />
        <Input label="职位" value={memberForm.position || ''} onChange={v => setMemberForm({ ...memberForm, position: v })} required />
        <Input label="部门" value={memberForm.department || ''} onChange={v => setMemberForm({ ...memberForm, department: v })} required />
        <Input label="邮箱" type="email" value={memberForm.email || ''} onChange={v => setMemberForm({ ...memberForm, email: v })} />
        <Input label="电话" value={memberForm.phone || ''} onChange={v => setMemberForm({ ...memberForm, phone: v })} />
        <Input label="入职日期" type="date" value={memberForm.joinDate || ''} onChange={v => setMemberForm({ ...memberForm, joinDate: v })} />
        <Select 
          label="状态" 
          value={memberForm.status || 'active'} 
          onChange={v => setMemberForm({ ...memberForm, status: v as 'active' | 'inactive' })} 
          options={[{ value: 'active', label: '在职' }, { value: 'inactive', label: '离职' }]} 
        />
        <TextArea label="个人简介" value={memberForm.bio || ''} onChange={v => setMemberForm({ ...memberForm, bio: v })} rows={3} />
        <div style={{ display: 'flex', gap: '8px', marginTop: '24px' }}>
          <Button variant="secondary" onClick={() => setTeamModalOpen(false)}>取消</Button>
          <Button variant="primary" onClick={handleSaveMember}>
            <Save size={16} />保存
          </Button>
        </div>
      </Modal>

      {/* News Modal */}
      <Modal isOpen={newsModalOpen} onClose={() => setNewsModalOpen(false)} title={editingNews ? '编辑动态' : '发布动态'} size="lg">
        <Input label="标题" value={newsForm.title || ''} onChange={v => setNewsForm({ ...newsForm, title: v })} required />
        <Select 
          label="分类" 
          value={newsForm.category || 'news'} 
          onChange={v => setNewsForm({ ...newsForm, category: v as 'announcement' | 'news' | 'activity' })} 
          options={[{ value: 'news', label: '新闻' }, { value: 'announcement', label: '公告' }, { value: 'activity', label: '活动' }]} 
        />
        <TextArea label="内容" value={newsForm.content || ''} onChange={v => setNewsForm({ ...newsForm, content: v })} required rows={10} />
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '16px' }}>
          <input 
            type="checkbox" 
            id="isTop" 
            checked={newsForm.isTop || false} 
            onChange={(e) => setNewsForm({ ...newsForm, isTop: e.target.checked })} 
          />
          <label htmlFor="isTop" style={{ cursor: 'pointer' }}>置顶显示</label>
        </div>
        <div style={{ display: 'flex', gap: '8px', marginTop: '24px' }}>
          <Button variant="secondary" onClick={() => setNewsModalOpen(false)}>取消</Button>
          <Button variant="primary" onClick={handleSaveNews}>
            <Save size={16} />发布
          </Button>
        </div>
      </Modal>
    </div>
  )
}
